  "location",
  "name",
  "navigator",
  "parent",
  "prototype",
  "scripts",
  "self",
  "top",
  "window",
])
const MARKDOWN_HEADING_NAMED_ENTITIES: Record<string, string> = {
  amp: "&",
  apos: "'",
  copy: "©",
  gt: ">",
  hellip: "…",
  laquo: "«",
  ldquo: "“",
  lsquo: "‘",
  lt: "<",
  mdash: "—",
  nbsp: " ",
  ndash: "–",
  quot: '"',
  raquo: "»",
  rdquo: "”",
  reg: "®",
  rsquo: "’",
  shy: "",
  trade: "™",
}

export type PretextMarkdownChunkKind = "frontmatter" | "markdown"
export type PretextMarkdownFrontmatterLanguage = "toml" | "yaml"
export type PretextMarkdownBlockKind =
  | "code"
  | "comment"
  | "definition"
  | "frontmatter"
  | "heading"
  | "html"
  | "list"
  | "paragraph"
  | "table"
  | "thematicBreak"
  | "unknown"

export interface PretextMarkdownDocument {
  blocks: PretextMarkdownBlock[]
  footnoteDefinitionsMarkdown: string
  frontmatter?: PretextMarkdownFrontmatter
  headings: PretextMarkdownHeading[]
  chunks: PretextMarkdownChunk[]
  referenceDefinitionsMarkdown: string
  sourceLineCount: number
  text: string
  wordCount: number
}

export interface PretextMarkdownHeading {
  blockId: string
  id: string
  chunkIndex: number
  sourceOffset: number
  sourceLine: number
  text: string
}

export interface PretextMarkdownFrontmatter {
  entries: PretextMarkdownFrontmatterEntry[]
  language: PretextMarkdownFrontmatterLanguage
  markdown: string
  sourceEndOffset: number
  sourceEndLine: number
  sourceStartOffset: number
  sourceStartLine: number
}

export interface PretextMarkdownFrontmatterEntry {
  key: string
  value: string
  valueKind: "boolean" | "list" | "number" | "string"
}

export interface PretextMarkdownBlock {
  chunkIndex: number
  frontmatterEntries?: PretextMarkdownFrontmatterEntry[]
  headingId?: string
  id: string
  index: number
  isOrderedList?: boolean
  isHostile: boolean
  kind: PretextMarkdownBlockKind
  listStart?: number
  markdown: string
  sourceEndOffset: number
  sourceEndLine: number
  sourceStartOffset: number
  sourceStartLine: number
}

export interface PretextMarkdownChunk {
  blockIds: string[]
  frontmatterEntries?: PretextMarkdownFrontmatterEntry[]
  frontmatterLanguage?: PretextMarkdownFrontmatterLanguage
  headingIds: string[]
  index: number
  isHostile: boolean
  kind: PretextMarkdownChunkKind
  markdown: string
  sourceEndOffset: number
  sourceEndLine: number
  sourceStartOffset: number
  sourceStartLine: number
}

export interface PretextMarkdownLineRange {
  end: number
  start: number
}

export interface PretextMarkdownOffsetRange {
  end: number
  start: number
}

export function createPretextMarkdownDocument(
  markdown: string
): PretextMarkdownDocument {
  const sourceLineCount = splitTextLines(markdown).length
  const { blocks, headings, chunks } = createPretextMarkdownChunks(
    markdown,
    sourceLineCount
  )
  const frontmatter =
    chunks[0]?.kind === "frontmatter"
      ? createPretextMarkdownFrontmatter(chunks[0])
      : undefined
  const referenceDefinitionsMarkdown =
    collectPretextMarkdownReferenceDefinitions(markdown)
  const footnoteDefinitionsMarkdown =
    collectPretextMarkdownFootnoteDefinitions(markdown)

  return {
    blocks,
    footnoteDefinitionsMarkdown,
    ...(frontmatter ? { frontmatter } : {}),
    headings,
    chunks,
    referenceDefinitionsMarkdown,
    sourceLineCount,
    text: markdown,
    wordCount: countWords(markdown),
  }
}

export function findPretextMarkdownChunkForOffset(
  chunks: readonly PretextMarkdownChunk[],
  sourceOffset: number
) {
  return chunks.find((chunk) =>
    pretextMarkdownSourceOffsetsIntersect({
      end: chunk.sourceEndOffset,
      point: sourceOffset,
      start: chunk.sourceStartOffset,
    })
  )
}

export function findPretextMarkdownBlockForOffset(
  blocks: readonly PretextMarkdownBlock[],
  sourceOffset: number
) {
  return blocks.find((block) =>
    pretextMarkdownSourceOffsetsIntersect({
      end: block.sourceEndOffset,
      point: sourceOffset,
      start: block.sourceStartOffset,
    })
  )
}

export function pretextMarkdownChunkIntersectsOffsetRange({
  chunk,
  range,
}: {
  chunk: PretextMarkdownChunk
  range: PretextMarkdownOffsetRange | null
}) {
  return pretextMarkdownSourceRangeIntersectsOffsetRange({
    range,
    sourceEndOffset: chunk.sourceEndOffset,
    sourceStartOffset: chunk.sourceStartOffset,
  })
}

export function pretextMarkdownBlockIntersectsOffsetRange({
  block,
  range,
}: {
  block: PretextMarkdownBlock
  range: PretextMarkdownOffsetRange | null
}) {
  return pretextMarkdownSourceRangeIntersectsOffsetRange({
    range,
    sourceEndOffset: block.sourceEndOffset,
    sourceStartOffset: block.sourceStartOffset,
  })
}

export function findPretextMarkdownHeadingById(
  document: PretextMarkdownDocument,
  headingId: string
) {
  return document.headings.find((heading) => heading.id === headingId)
}

function pretextMarkdownSourceRangeIntersectsOffsetRange({
  range,
  sourceEndOffset,
  sourceStartOffset,
}: {
  range: PretextMarkdownOffsetRange | null
  sourceEndOffset: number
  sourceStartOffset: number
}) {
  if (!range) return false
  const start = Math.max(0, Math.min(range.start, range.end))
  const end = Math.max(0, Math.max(range.start, range.end))
  return sourceStartOffset < end && sourceEndOffset > start
}

function pretextMarkdownSourceOffsetsIntersect({
  end,
  point,
  start,
}: {
  end: number
  point: number
  start: number
}) {
  return point >= start && point < end
}

function createPretextMarkdownChunks(
  markdown: string,
  sourceLineCount: number
): Pick<PretextMarkdownDocument, "blocks" | "headings" | "chunks"> {
  const blockIds: BlockIdRegistry = new Map()
  const blocks: PretextMarkdownBlock[] = []
  const chunks: PretextMarkdownChunk[] = []
  const headings: PretextMarkdownHeading[] = []
  const headingIds: HeadingIdRegistry = new Map()
  const sourceLineOffsets = createSourceLineOffsets(markdown)
  const frontmatter = extractFrontmatter(markdown)
  const body = frontmatter ? frontmatter.body : markdown
  const bodyStartLine = frontmatter ? frontmatter.endLine + 1 : 1

  if (frontmatter) {
    const chunkIndex = chunks.length
    const sourceStartOffset = getSourceLineStartOffset(sourceLineOffsets, 1)
    const sourceEndOffset = getSourceLineEndOffset(
      sourceLineOffsets,
      frontmatter.endLine,
      markdown.length
    )
    const frontmatterEntries = parsePretextMarkdownFrontmatterEntries({
      language: frontmatter.language,
      markdown: frontmatter.text,
    })
    const block = createPretextMarkdownBlock({
      blockIds,
      blocks,
      chunkIndex,
      frontmatterEntries,
      isHostile: false,
      kind: "frontmatter",
      markdown: frontmatter.text,
      sourceEndOffset,
      sourceEndLine: frontmatter.endLine,
      sourceStartOffset,
      sourceStartLine: 1,
    })
    chunks.push({
      blockIds: [block.id],
      frontmatterEntries,
      headingIds: [],
      index: chunkIndex,
      frontmatterLanguage: frontmatter.language,
      isHostile: false,
      kind: "frontmatter",
      markdown: frontmatter.text,
      sourceEndOffset,
      sourceEndLine: frontmatter.endLine,
      sourceStartOffset,
      sourceStartLine: 1,
    })
  }

  const bodyChunks = createMarkdownBodyChunks({
    blockIds,
    blocks,
    headingIds,
    headings,
    markdown: body,
    sourceLineOffsets,
    sourceEndLine: sourceLineCount,
    sourceStartLine: bodyStartLine,
    textLength: markdown.length,
    startIndex: chunks.length,
  })
  chunks.push(...bodyChunks)

  if (!chunks.length) {
    chunks.push({
      blockIds: [],
      headingIds: [],
      index: 0,
      isHostile: false,
      kind: "markdown",
      markdown,
      sourceEndOffset: markdown.length,
      sourceEndLine: sourceLineCount,
      sourceStartOffset: 0,
      sourceStartLine: 1,
    })
  }

  return { blocks, headings, chunks }
}

function createMarkdownBodyChunks({
  blockIds,
  blocks,
  headingIds,
  headings,
  markdown,
  sourceLineOffsets,
  sourceEndLine,
  sourceStartLine,
  textLength,
  startIndex,
}: {
  blockIds: BlockIdRegistry
  blocks: PretextMarkdownBlock[]
  headingIds: HeadingIdRegistry
  headings: PretextMarkdownHeading[]
  markdown: string
  sourceLineOffsets: SourceLineOffsets
  sourceEndLine: number
  sourceStartLine: number
  textLength: number
  startIndex: number
}) {
  const chunks: PretextMarkdownChunk[] = []
  if (!markdown.trim()) return chunks

  const accumulator = new ChunkAccumulator({
    chunks,
    sourceLineOffsets,
    startIndex,
    startLine: sourceStartLine,
    textLength,
  })

  try {
    const tokens = parsePretextMarkdownTokens(markdown)
    let cursorLine = sourceStartLine
    let cursorOffset = getSourceLineStartOffset(
      sourceLineOffsets,
      sourceStartLine
    )

    for (const token of tokens) {
      const raw = token.raw ?? ""
      const tokenLineCount = countLines(raw)
      const tokenLineBreaks = countLineSeparators(raw)
      const tokenStartLine = cursorLine
      const tokenStartOffset = cursorOffset
      const tokenEndOffset = Math.min(textLength, tokenStartOffset + raw.length)
      const tokenEndLine = Math.min(
        sourceEndLine,
        Math.max(tokenStartLine, cursorLine + Math.max(0, tokenLineCount - 1))
      )
      cursorLine += tokenLineBreaks
      cursorOffset = tokenEndOffset

      if (token.kind === "space") {
        accumulator.addSpace(raw, tokenLineBreaks)
        continue
      }

      const tokenIsHostile = isHostilePretextMarkdownToken(token, raw)
      const shouldStartNewChunk =
        accumulator.hasContent() &&
        isChunkLeadToken(token) &&
        accumulator.lineCount >= MARKDOWN_CHUNK_TARGET_SOURCE_LINES
      const wouldExceedMax =
        accumulator.hasContent() &&
        accumulator.lineCount + Math.max(1, tokenLineCount) >
          MARKDOWN_CHUNK_MAX_SOURCE_LINES

      if (shouldStartNewChunk || wouldExceedMax || tokenIsHostile) {
        accumulator.flush(
          Math.max(accumulator.startLine, tokenStartLine - 1)
        )
        accumulator.startAt(tokenStartLine, tokenStartOffset)
      }

      const chunkIndex = startIndex + chunks.length
      const blockKind = pretextMarkdownBlockKindForToken(token)
      const block = createPretextMarkdownBlock({
        blockIds,
        blocks,
        chunkIndex,
        isHostile: tokenIsHostile,
        kind: blockKind,
        markdown: raw,
        sourceEndOffset: tokenEndOffset,
        sourceEndLine: tokenEndLine,
        sourceStartOffset: tokenStartOffset,
        sourceStartLine: tokenStartLine,
      })
      accumulator.addBlockId(block.id)

      if (token.kind === "heading") {
        const text = normalizeHeadingText(token.text)
        const id = createMarkdownHeadingId(text, headingIds)
        block.headingId = id
        accumulator.addHeadingId(id)
        headings.push({
          blockId: block.id,
          id,
          chunkIndex,
          sourceOffset: tokenStartOffset,
          sourceLine: tokenStartLine,
          text,
        })
      }
      if (token.kind === "list") {
        block.isOrderedList = token.isOrderedList
        block.listStart = token.listStart
      }

      accumulator.addToken(raw, Math.max(1, tokenLineCount), tokenIsHostile)
      if (
        tokenIsHostile ||
        accumulator.lineCount >= MARKDOWN_CHUNK_MAX_SOURCE_LINES
      ) {
        accumulator.flush(tokenEndLine)
      }
    }

    if (accumulator.hasContent()) {
      accumulator.flush(sourceEndLine)
    }
  } catch {
    const block = createPretextMarkdownBlock({
      blockIds,
      blocks,
      chunkIndex: startIndex,
      isHostile: isHostilePretextMarkdownChunk(markdown),
      kind: "unknown",
      markdown,
      sourceEndOffset: textLength,
      sourceEndLine,
      sourceStartOffset: getSourceLineStartOffset(
        sourceLineOffsets,
        sourceStartLine
      ),
      sourceStartLine,
    })
    chunks.push({
      blockIds: [block.id],
      headingIds: [],
      index: startIndex,
      isHostile: block.isHostile,
      kind: "markdown",
      markdown,
      sourceEndOffset: block.sourceEndOffset,
      sourceEndLine,
      sourceStartOffset: block.sourceStartOffset,
      sourceStartLine,
    })
  }

  return chunks
}

/**
 * Accumulates raw markdown, block/heading ids, line counts, and the hostile
 * flag for the chunk currently being built, then emits a fully-formed
 * PretextMarkdownChunk on flush. Encapsulates what was previously a set of
 * mutually-mutating free `let` bindings in createMarkdownBodyChunks.
 */
class ChunkAccumulator {
  private readonly chunks: PretextMarkdownChunk[]
  private readonly sourceLineOffsets: SourceLineOffsets
  private readonly startIndex: number
  private readonly textLength: number

  private raw = ""
  private blockIds: string[] = []
  private headingIds: string[] = []
  private isHostile = false

  /** Number of source lines spanned by the in-progress chunk. */
  lineCount = 0
  /** First source line of the in-progress chunk (1-based). */
  startLine: number
  /** Source offset of the first character of the in-progress chunk. */
  startOffset: number

  constructor({
    chunks,
    sourceLineOffsets,
    startIndex,
    startLine,
    textLength,
  }: {
    chunks: PretextMarkdownChunk[]
    sourceLineOffsets: SourceLineOffsets
    startIndex: number
    startLine: number
    textLength: number
  }) {
    this.chunks = chunks
    this.sourceLineOffsets = sourceLineOffsets
    this.startIndex = startIndex
    this.textLength = textLength
    this.startLine = startLine
    this.startOffset = getSourceLineStartOffset(sourceLineOffsets, startLine)
  }

  /** True when the chunk has any non-whitespace content. */
  hasContent() {
    return this.raw.trim().length > 0
  }

  /** Append whitespace-only ("space") token content without block tracking. */
  addSpace(raw: string, lineBreaks: number) {
    this.raw += raw
    this.lineCount += lineBreaks
  }

  /** Append a content token's raw text, line count, and hostile flag. */
  addToken(raw: string, lineCount: number, tokenIsHostile: boolean) {
    this.raw += raw
    this.lineCount += lineCount
    this.isHostile = this.isHostile || tokenIsHostile
  }

  addBlockId(id: string) {
    this.blockIds.push(id)
  }

  addHeadingId(id: string) {
    this.headingIds.push(id)
  }

  /** Override the start position of the in-progress chunk. */
  startAt(startLine: number, startOffset: number) {
    this.startLine = startLine
    this.startOffset = startOffset
  }

  /**
   * Emit the in-progress chunk (when it has content) and reset accumulator
   * state to begin the next chunk after `endLine`. Whitespace-only chunks are
   * dropped but still advance the start position, matching the original
   * flushChunk closure exactly.
   */
  flush(endLine: number) {
    if (!this.hasContent()) {
      this.resetTo(endLine)
      return
    }
    const chunkIndex = this.startIndex + this.chunks.length
    const chunkMarkdown = this.raw.replace(/\n+$/g, "")
    this.chunks.push({
      blockIds: this.blockIds,
      headingIds: this.headingIds,
      index: chunkIndex,
      isHostile: this.isHostile,
      kind: "markdown",
      markdown: chunkMarkdown,
      sourceEndOffset: Math.min(
        this.textLength,
        this.startOffset + chunkMarkdown.length
      ),
      sourceEndLine: Math.max(this.startLine, endLine),
      sourceStartOffset: this.startOffset,
      sourceStartLine: this.startLine,
    })
    this.blockIds = []
    this.headingIds = []
    this.resetTo(endLine)
  }

  /** Reset accumulation state and advance the start position past `endLine`. */
  private resetTo(endLine: number) {
    this.raw = ""
    this.lineCount = 0
    this.isHostile = false
    this.startLine = endLine + 1
    this.startOffset = getSourceLineStartOffset(
      this.sourceLineOffsets,
      this.startLine
    )
  }
}

function extractFrontmatter(markdown: string) {
  const lines = splitTextLines(markdown)
  const openingFence = lines[0]?.trim()
  const language = frontmatterLanguageForFence(openingFence)
  if (!language || !openingFence) return null

  for (let index = 1; index < lines.length; index++) {
    if (lines[index]!.trim() !== openingFence) continue
    if (index === 1) return null
    return {
      body: lines.slice(index + 1).join("\n"),
      endLine: index + 1,
      language,
      text: lines.slice(1, index).join("\n"),
    }
  }

  return null
}

function frontmatterLanguageForFence(
  fence: string | undefined
): PretextMarkdownFrontmatterLanguage | null {
  switch (fence) {
    case "---":
      return "yaml"
    case "+++":
      return "toml"
    default:
      return null
  }
}

function collectPretextMarkdownReferenceDefinitions(markdown: string) {
  const frontmatter = extractFrontmatter(markdown)
  const body = frontmatter ? frontmatter.body : markdown

  try {
    return parsePretextMarkdownTokens(body)
      .filter((token) => token.kind === "definition")
      .map((token) => token.raw.trimEnd())
      .filter(Boolean)
      .join("\n")
  } catch {
    return ""
  }
}

function collectPretextMarkdownFootnoteDefinitions(markdown: string) {
  const frontmatter = extractFrontmatter(markdown)
  const body = frontmatter ? frontmatter.body : markdown

  return splitTextLines(body)
    .map((line) => line.trimEnd())
    .filter((line) => /^\[\^[^\]\r\n]+\]:[ \t]?.+/u.test(line))
    .join("\n")
}

function countLines(text: string) {
  if (!text) return 1
  return text.split(/\r\n|[\n\r\u2028\u2029]/).length
}

function countLineSeparators(text: string) {
  if (!text) return 0
  return Math.max(0, countLines(text) - 1)
}

type HeadingIdRegistry = Map<string, number>
type BlockIdRegistry = Map<string, number>

function createPretextMarkdownBlock({
  blockIds,
  blocks,
  chunkIndex,
  frontmatterEntries,
  isHostile,
  kind,
  markdown,
  sourceEndOffset,
  sourceEndLine,
  sourceStartOffset,
  sourceStartLine,
}: {
  blockIds: BlockIdRegistry
  blocks: PretextMarkdownBlock[]
  chunkIndex: number
  frontmatterEntries?: PretextMarkdownFrontmatterEntry[]
  isHostile: boolean
  kind: PretextMarkdownBlockKind
  markdown: string
  sourceEndOffset: number
  sourceEndLine: number
  sourceStartOffset: number
  sourceStartLine: number
}) {
  const block: PretextMarkdownBlock = {
    chunkIndex,
    frontmatterEntries,
    id: createMarkdownBlockId({ blockIds, kind, sourceStartLine }),
    index: blocks.length,
    isHostile,
    kind,
    markdown,
    sourceEndOffset,
    sourceEndLine,
    sourceStartOffset,
    sourceStartLine,
  }
  blocks.push(block)
  return block
}

function createPretextMarkdownFrontmatter(
  chunk: PretextMarkdownChunk
): PretextMarkdownFrontmatter | undefined {
  if (!chunk.frontmatterLanguage) return undefined
  return {
    entries: chunk.frontmatterEntries ?? [],
    language: chunk.frontmatterLanguage,
    markdown: chunk.markdown,
    sourceEndOffset: chunk.sourceEndOffset,
    sourceEndLine: chunk.sourceEndLine,
    sourceStartOffset: chunk.sourceStartOffset,
    sourceStartLine: chunk.sourceStartLine,
  }
}

interface SourceLineOffsets {
  ends: number[]
  starts: number[]
}

function createSourceLineOffsets(text: string): SourceLineOffsets {
  const starts: number[] = []
  const ends: number[] = []
  const lineSeparatorPattern = /\r\n|[\n\r\u2028\u2029]/g
  let lineStart = 0
  let match: RegExpExecArray | null

  while ((match = lineSeparatorPattern.exec(text))) {
    starts.push(lineStart)
    ends.push(match.index)
    lineStart = match.index + match[0].length
  }

  starts.push(lineStart)
  ends.push(text.length)
  return { ends, starts }
}

function getSourceLineStartOffset(offsets: SourceLineOffsets, line: number) {
  return (
    offsets.starts[Math.max(0, line - 1)] ??
    offsets.ends[offsets.ends.length - 1] ??
    0
  )
}

function getSourceLineEndOffset(
  offsets: SourceLineOffsets,
  line: number,
  textLength: number
) {
  return offsets.ends[Math.max(0, line - 1)] ?? textLength
}

function parsePretextMarkdownFrontmatterEntries({
  language,
  markdown,
}: {
  language: PretextMarkdownFrontmatterLanguage
  markdown: string
}): PretextMarkdownFrontmatterEntry[] {
  const entries: PretextMarkdownFrontmatterEntry[] = []
  let tomlSection: string | null = null
  const lines = markdown.split(/\r?\n/)

  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index]!
    if (language === "toml") {
      const section = /^\s*\[([A-Za-z_][\w.-]*)\]\s*$/.exec(line)
      if (section) {
        tomlSection = section[1]!
        continue
      }
    }

    if (language === "yaml") {
      const entry = parsePretextMarkdownYamlFrontmatterEntry(line)
      if (entry) {
        entries.push(entry)
        continue
      }

      const listEntry = parsePretextMarkdownYamlFrontmatterListEntry(
        line,
        lines,
        index
      )
      if (listEntry) {
        entries.push(listEntry.entry)
        index = listEntry.endIndex
      }
      continue
    }

    const entry = parsePretextMarkdownTomlFrontmatterEntry(line, tomlSection)
    if (entry) entries.push(entry)
  }

  return entries
}

function parsePretextMarkdownYamlFrontmatterEntry(
  line: string
): PretextMarkdownFrontmatterEntry | null {
  const trimmed = line.trim()
  if (!trimmed || trimmed.startsWith("#")) return null

  const match = /^([A-Za-z_][\w.-]*)\s*:\s*(.*?)\s*$/.exec(trimmed)
  if (!match) return null
  const value = parsePretextMarkdownFrontmatterScalar(match[2]!)
  if (!value) return null

  return {
    key: match[1]!,
    ...value,
  }
}

function parsePretextMarkdownYamlFrontmatterListEntry(
  line: string,
  lines: readonly string[],
  startIndex: number
): { endIndex: number; entry: PretextMarkdownFrontmatterEntry } | null {
  const match = /^([A-Za-z_][\w.-]*)\s*:\s*$/.exec(line.trim())
  if (!match) return null

  const values: string[] = []
  let endIndex = startIndex
  for (let index = startIndex + 1; index < lines.length; index += 1) {
    const itemMatch = /^\s+-\s*(.*?)\s*$/.exec(lines[index]!)
    if (!itemMatch) break

    const value = parsePretextMarkdownFrontmatterScalar(itemMatch[1]!)
    if (!value || value.valueKind === "list") return null
    values.push(value.value)
    endIndex = index
  }

  if (!values.length) return null

  return {
    endIndex,
    entry: {
      key: match[1]!,
      value: values.join(", "),
      valueKind: "list",
    },
  }
}

function parsePretextMarkdownTomlFrontmatterEntry(
  line: string,
  section: string | null
): PretextMarkdownFrontmatterEntry | null {
  const trimmed = line.trim()
  if (!trimmed || trimmed.startsWith("#") || trimmed.startsWith("[")) {
    return null
  }

  const match = /^([A-Za-z_][\w.-]*)\s*=\s*(.*?)\s*$/.exec(trimmed)
  if (!match) return null
  const value = parsePretextMarkdownFrontmatterScalar(match[2]!)
  if (!value) return null

  return {
    key: section ? `${section}.${match[1]!}` : match[1]!,
    ...value,
  }
}

function parsePretextMarkdownFrontmatterScalar(
  rawValue: string
): Pick<PretextMarkdownFrontmatterEntry, "value" | "valueKind"> | null {
  const value = rawValue.trim()
  if (!value) return null

  const list = parsePretextMarkdownFrontmatterInlineList(value)
  if (list) {
    return {
      value: list.join(", "),
      valueKind: "list",
    }
  }

  if (/^[{[>|]/.test(value)) return null

  return parsePretextMarkdownFrontmatterScalarAtom(value)
}

function parsePretextMarkdownFrontmatterInlineList(
  value: string
): string[] | null {
  if (!value.startsWith("[") || !value.endsWith("]")) return null

  const inner = value.slice(1, -1).trim()
  if (!inner) return null

  const values: string[] = []
  for (const item of inner.split(",")) {
    const scalar = parsePretextMarkdownFrontmatterScalarAtom(item.trim())
    if (!scalar || scalar.valueKind === "list") return null
    values.push(scalar.value)
  }
  return values
}

function parsePretextMarkdownFrontmatterScalarAtom(
  rawValue: string
): Pick<PretextMarkdownFrontmatterEntry, "value" | "valueKind"> | null {
  const value = rawValue.trim()
  if (!value || /^[{[>|]/.test(value)) return null
  const quoted = /^"([^"]*)"$/.exec(value) ?? /^'([^']*)'$/.exec(value)
  if (quoted) {
    return {
      value: quoted[1]!,
      valueKind: "string",
    }
  }

  if (/^(?:true|false)$/i.test(value)) {
    return {
      value: value.toLowerCase(),
      valueKind: "boolean",
    }
  }

  if (/^-?\d+(?:\.\d+)?$/.test(value)) {
    return {
      value,
      valueKind: "number",
    }
  }

  if (/[:#]/.test(value)) return null

  return {
    value,
    valueKind: "string",
  }
}

function createMarkdownBlockId({
  blockIds,
  kind,
  sourceStartLine,
}: {
  blockIds: BlockIdRegistry
  kind: PretextMarkdownBlockKind
  sourceStartLine: number
}) {
  const base = `block-${sourceStartLine}-${kind}`
  const count = blockIds.get(base) ?? 0
  blockIds.set(base, count + 1)
  return count === 0 ? base : `${base}-${count}`
}

function pretextMarkdownBlockKindForToken(
  token: PretextMarkdownToken
): PretextMarkdownBlockKind {
  switch (token.kind) {
    case "code":
    case "comment":
    case "definition":
    case "heading":
    case "html":
    case "list":
    case "paragraph":
    case "table":
      return token.kind
    case "hr":
      return "thematicBreak"
    default:
      return "unknown"
  }
}

function createMarkdownHeadingId(text: string, headingIds: HeadingIdRegistry) {
  const base = createPretextMarkdownHeadingSlug(text)
  const count = headingIds.get(base) ?? 0
  headingIds.set(base, count + 1)
  return count === 0 ? base : `${base}-${count}`
}

export function createPretextMarkdownHeadingSlug(text: string) {
  return namespaceMarkdownHeadingId(slugifyMarkdownHeading(text))
}

function namespaceMarkdownHeadingId(slug: string) {
  const base = slug || "section"
  return DOM_CLOBBERING_HEADING_IDS.has(base) ? `section-${base}` : base
}

function slugifyMarkdownHeading(text: string) {
  return text
    .trim()
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[^\p{Letter}\p{Number}\s_-]/gu, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "")
}

function normalizeHeadingText(text: string) {
  return decodeMarkdownHeadingEntities(text).replace(/\s+/g, " ").trim()
}

function decodeMarkdownHeadingEntities(text: string) {
  return text.replace(
    /&(#x[\da-f]+|#\d+|[a-z][a-z\d]+);/gi,
    (entity, body: string) => {
      if (body.startsWith("#x") || body.startsWith("#X")) {
        return decodeMarkdownNumericEntity(entity, body.slice(2), 16)
      }
      if (body.startsWith("#")) {
        return decodeMarkdownNumericEntity(entity, body.slice(1), 10)
      }

      return MARKDOWN_HEADING_NAMED_ENTITIES[body.toLowerCase()] ?? entity
    }
  )
}

function decodeMarkdownNumericEntity(
  entity: string,
  rawCodePoint: string,
  radix: number
) {
  const codePoint = Number.parseInt(rawCodePoint, radix)
  if (
    !Number.isFinite(codePoint) ||
    codePoint <= 0 ||
    codePoint > 0x10ffff ||
    (codePoint >= 0xd800 && codePoint <= 0xdfff)
  ) {
    return entity
  }

  try {
    return String.fromCodePoint(codePoint)
  } catch {
    return entity
  }
}

function isChunkLeadToken(token: PretextMarkdownToken) {
  return token.kind === "heading" || token.kind === "hr"
}

export function isHostilePretextMarkdownChunk(markdown: string) {
  try {
    return parsePretextMarkdownTokens(markdown).some((token) =>
      token.kind === "space"
        ? false
        : isHostilePretextMarkdownToken(token, token.raw)
    )
  } catch {
    return markdown.length > 20_000
  }
}

function isHostilePretextMarkdownToken(
  token: PretextMarkdownToken,
  raw: string
) {
  const lineCount = countLines(raw)

  switch (token.kind) {
    case "code":
      return lineCount > 400
    case "table":
      return Math.max(0, lineCount - 2) > 200
    case "paragraph":
      return raw.length > 20_000
    case "list":
      return lineCount > 500
    case "html":
      return raw.length > 20_000
    default:
      return false
  }
}

function countWords(text: string) {
  return text.trim().split(/\s+/).filter(Boolean).length
}

"use client"

import {
  measureLineStats,
  prepareWithSegments,
  type PreparedTextWithSegments,
} from "@chenglou/pretext"

import type {
  PretextMarkdownBlock,
  PretextMarkdownChunk,
  PretextMarkdownChunkKind,
  PretextMarkdownDocument,
} from "./pretext-markdown-document-model"
import { splitTextLines } from "./text-viewer-resource"

const DOCUMENT_PADDING_Y = 32
const CHUNK_GAP = 0
const CHUNK_PADDING_X = 48
const CHUNK_PADDING_Y = 0
const BODY_LINE_HEIGHT = 24
const CODE_LINE_HEIGHT = 21
const BLOCK_GAP = 8
const MIN_CHUNK_HEIGHT = 120
const COMPONENT_FALLBACK_MIN_HEIGHT = 112
const APPROX_CHAR_WIDTH_PX = 8
const BODY_FONT_FAMILY =
  'ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif'
const CODE_FONT_FAMILY =
  'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace'

export interface PretextMarkdownDocumentFrame {
  chunks: PretextMarkdownChunkFrame[]
  totalHeight: number
  width: number
}

export interface PretextMarkdownChunkFrame {
  blockIds: string[]
  bottom: number
  estimatedHeight: number
  height: number
  index: number
  isHostile: boolean
  kind: PretextMarkdownChunkKind
  measuredHeight: number | null
  sourceEndLine: number
  sourceStartLine: number
  top: number
}

export interface PretextMarkdownMeasuredHeights {
  get(index: number): number | undefined
}

export function layoutPretextMarkdownDocument({
  contentWidth,
  document,
  fontScale,
  measuredHeights,
}: {
  contentWidth: number
  document: PretextMarkdownDocument
  fontScale: number
  measuredHeights?: PretextMarkdownMeasuredHeights
}): PretextMarkdownDocumentFrame {
  const width = Math.max(1, contentWidth)
  const blocksById = new Map(
    document.blocks.map((block) => [block.id, block] as const)
  )
  const frames: PretextMarkdownChunkFrame[] = []
  let y = DOCUMENT_PADDING_Y

  for (const chunk of document.chunks) {
    const measuredHeight = measuredHeights?.get(chunk.index)
    const estimatedHeight = estimatePretextMarkdownChunkHeight({
      blocksById,
      fontScale,
      chunk,
      width,
    })
    const height =
      measuredHeight == null
        ? estimatedHeight
        : Math.max(MIN_CHUNK_HEIGHT, measuredHeight)
    const frame: PretextMarkdownChunkFrame = {
      blockIds: chunk.blockIds,
      bottom: y + height,
      estimatedHeight,
      height,
      index: chunk.index,
      isHostile: chunk.isHostile,
      kind: chunk.kind,
      measuredHeight: measuredHeight ?? null,
      sourceEndLine: chunk.sourceEndLine,
      sourceStartLine: chunk.sourceStartLine,
      top: y,
    }
    frames.push(frame)
    y = frame.bottom + CHUNK_GAP
  }

  return {
    chunks: frames,
    totalHeight: frames.length ? y - CHUNK_GAP + DOCUMENT_PADDING_Y : 0,
    width,
  }
}

export function estimatePretextMarkdownChunkHeight({
  blocksById,
  fontScale,
  chunk,
  width,
}: {
  blocksById?: ReadonlyMap<string, PretextMarkdownBlock>
  fontScale: number
  chunk: PretextMarkdownChunk
  width: number
}) {
  const textWidth = Math.max(1, width - CHUNK_PADDING_X * 2)
  const blocks = chunk.blockIds
    .map((blockId) => blocksById?.get(blockId))
    .filter((block): block is PretextMarkdownBlock => Boolean(block))

  if (blocks.length > 0) {
    return estimatePretextMarkdownBlocksHeight({
      blocks,
      fontScale,
      textWidth,
    })
  }

  if (chunk.isHostile) {
    return estimateHostilePretextMarkdownChunkHeight({
      chunk,
      fontScale,
      textWidth,
    })
  }

  const fontSize = chunk.kind === "frontmatter" ? 13 : 16
  const lineHeight =
    chunk.kind === "frontmatter" ? CODE_LINE_HEIGHT : BODY_LINE_HEIGHT
  const fontFamily =
    chunk.kind === "frontmatter" ? CODE_FONT_FAMILY : BODY_FONT_FAMILY
  const font = `${Math.round(fontSize * fontScale)}px ${fontFamily}`
  const lineCount = measureWrappedLineCount(
    chunk.markdown,
    font,
    textWidth / fontScale
  )
  const syntaxAllowance = estimateMarkdownSyntaxAllowance(chunk)
  return Math.max(
    MIN_CHUNK_HEIGHT,
    CHUNK_PADDING_Y * 2 + lineCount * lineHeight * fontScale + syntaxAllowance
  )
}

function estimatePretextMarkdownBlocksHeight({
  blocks,
  fontScale,
  textWidth,
}: {
  blocks: readonly PretextMarkdownBlock[]
  fontScale: number
  textWidth: number
}) {
  const visibleBlocks = blocks.filter(isVisiblePretextMarkdownBlock)
  if (!visibleBlocks.length) return 0

  const height = visibleBlocks.reduce(
    (sum, block, index) =>
      sum +
      estimatePretextMarkdownBlockHeight({
        block,
        fontScale,
        textWidth,
      }) +
      (index === visibleBlocks.length - 1 ? 0 : BLOCK_GAP * fontScale),
    CHUNK_PADDING_Y * 2
  )
  return Math.max(MIN_CHUNK_HEIGHT, height)
}

export function estimatePretextMarkdownBlockHeight({
  block,
  fontScale,
  textWidth,
}: {
  block: PretextMarkdownBlock
  fontScale: number
  textWidth: number
}) {
  if (block.kind === "comment" || block.kind === "definition") return 0

  if (block.isHostile) {
    return estimateHostilePretextMarkdownBlockHeight({
      block,
      fontScale,
      textWidth,
    })
  }

  if (isPretextMarkdownComponentLikeBlock(block)) {
    return estimatePretextMarkdownComponentFallbackBlockHeight({
      block,
      fontScale,
      textWidth,
    })
  }

  if (isPretextMarkdownMermaidCodeBlock(block)) {
    return (
      (36 +
        estimatePretextMarkdownDiagramBodyHeight(
          extractPretextMarkdownFenceBody(block.markdown)
        ) +
        40) *
      fontScale
    )
  }

  const fontSize = pretextMarkdownBlockFontSize(block)
  const lineHeight = pretextMarkdownBlockLineHeight(block)
  const fontFamily = pretextMarkdownBlockFontFamily(block)
  const font = `${Math.round(fontSize * fontScale)}px ${fontFamily}`
  const lineCount = measureWrappedLineCount(
    block.markdown,
    font,
    textWidth / fontScale
  )
  return (
    lineCount * lineHeight * fontScale +
    estimatePretextMarkdownBlockSyntaxAllowance(block, fontScale)
  )
}

function estimateHostilePretextMarkdownChunkHeight({
  chunk,
  fontScale,
  textWidth,
}: {
  chunk: PretextMarkdownChunk
  fontScale: number
  textWidth: number
}) {
  const estimatedWrappedLines = estimateWrappedLineCount(
    chunk.markdown,
    fontScale,
    textWidth
  )
  const syntaxAllowance = estimateMarkdownSyntaxAllowance(chunk)

  return Math.max(
    MIN_CHUNK_HEIGHT,
    CHUNK_PADDING_Y * 2 +
      estimatedWrappedLines * BODY_LINE_HEIGHT * fontScale +
      syntaxAllowance
  )
}

function estimateHostilePretextMarkdownBlockHeight({
  block,
  fontScale,
  textWidth,
}: {
  block: PretextMarkdownBlock
  fontScale: number
  textWidth: number
}) {
  const estimatedWrappedLines = estimateWrappedLineCount(
    block.markdown,
    fontScale,
    textWidth
  )

  return (
    estimatedWrappedLines * pretextMarkdownBlockLineHeight(block) * fontScale +
    estimatePretextMarkdownBlockSyntaxAllowance(block, fontScale)
  )
}

function isPretextMarkdownMermaidCodeBlock(block: PretextMarkdownBlock) {
  if (block.kind !== "code") return false
  const openingFence = splitTextLines(block.markdown)[0] ?? ""
  const language = openingFence
    .replace(/^`{3,}|^~{3,}/, "")
    .trim()
    .split(/\s+/)[0]
    ?.toLowerCase()
  return (
    language === "mermaid" || language === "mmd" || language === "mermaid-js"
  )
}

function extractPretextMarkdownFenceBody(markdown: string) {
  const lines = splitTextLines(markdown)
  if (lines.length <= 2) return ""
  return lines.slice(1, -1).join("\n")
}

function estimatePretextMarkdownDiagramBodyHeight(source: string) {
  const lines = source
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line && !line.startsWith("%%"))
  const header = lines[0]?.match(/^(?:graph|flowchart)\s+(TD|TB|BT|LR|RL)$/i)

  if (header) {
    const nodeIds = new Set<string>()
    for (const line of lines.slice(1)) {
      const edge = line.match(/^(.+?)\s*(?:-->|---|==>|-.->)\s*(.+?)$/)
      if (!edge) continue
      nodeIds.add(parsePretextMarkdownMermaidNodeId(edge[1]!))
      nodeIds.add(parsePretextMarkdownMermaidNodeId(edge[2]!))
    }

    const direction = header[1]!.toUpperCase()
    if (direction === "LR" || direction === "RL") return 160

    const nodeCount = Math.max(2, nodeIds.size)
    return clampPretextMarkdownDiagramBodyHeight(
      nodeCount * 42 + Math.max(0, nodeCount - 1) * 56 + 48
    )
  }

  return clampPretextMarkdownDiagramBodyHeight(lines.length * 28 + 96)
}

function parsePretextMarkdownMermaidNodeId(value: string) {
  const trimmed = value.trim()
  const match =
    trimmed.match(/^([A-Za-z0-9_-]+)\s*\[".+"]$/) ??
    trimmed.match(/^([A-Za-z0-9_-]+)\s*\[.+]$/) ??
    trimmed.match(/^([A-Za-z0-9_-]+)\s*\(.+\)$/)
  if (match) return match[1]!

  return trimmed.replace(/[^A-Za-z0-9_-].*$/, "") || trimmed
}

function clampPretextMarkdownDiagramBodyHeight(height: number) {
  return Math.min(520, Math.max(160, Math.ceil(height)))
}

function estimatePretextMarkdownComponentFallbackBlockHeight({
  block,
  fontScale,
  textWidth,
}: {
  block: PretextMarkdownBlock
  fontScale: number
  textWidth: number
}) {
  const font = `${Math.round(13 * fontScale)}px ${CODE_FONT_FAMILY}`
  const lineCount = measureWrappedLineCount(
    block.markdown,
    font,
    textWidth / fontScale
  )

  return Math.max(
    COMPONENT_FALLBACK_MIN_HEIGHT * fontScale,
    64 * fontScale + lineCount * CODE_LINE_HEIGHT * fontScale
  )
}

function estimateMarkdownSyntaxAllowance(chunk: PretextMarkdownChunk) {
  if (chunk.kind === "frontmatter") return 0
  let allowance = 0
  for (const line of splitTextLines(chunk.markdown)) {
    if (/^#{1,6}\s+/.test(line)) allowance += 18
    if (/^\s*[-*+]\s+/.test(line)) allowance += 3
    if (/^\s*>/.test(line)) allowance += 4
    if (/^\s*\|.*\|\s*$/.test(line)) allowance += 8
    if (/^\s*```/.test(line)) allowance += 16
  }
  return allowance
}

function pretextMarkdownBlockFontSize(block: PretextMarkdownBlock) {
  return isPretextMarkdownCodeLikeBlock(block) ? 13 : 16
}

function pretextMarkdownBlockLineHeight(block: PretextMarkdownBlock) {
  return isPretextMarkdownCodeLikeBlock(block)
    ? CODE_LINE_HEIGHT
    : BODY_LINE_HEIGHT
}

function pretextMarkdownBlockFontFamily(block: PretextMarkdownBlock) {
  return isPretextMarkdownCodeLikeBlock(block)
    ? CODE_FONT_FAMILY
    : BODY_FONT_FAMILY
}

function isPretextMarkdownCodeLikeBlock(block: PretextMarkdownBlock) {
  return (
    block.kind === "code" ||
    block.kind === "frontmatter" ||
    block.kind === "html"
  )
}

function isPretextMarkdownComponentLikeBlock(block: PretextMarkdownBlock) {
  return (
    block.kind === "html" &&
    /^<\/?[A-Z][A-Za-z0-9.]*(?:\s|\/?>)/.test(block.markdown.trim())
  )
}

function isVisiblePretextMarkdownBlock(block: PretextMarkdownBlock) {
  return block.kind !== "comment" && block.kind !== "definition"
}

function estimatePretextMarkdownBlockSyntaxAllowance(
  block: PretextMarkdownBlock,
  fontScale: number
) {
  switch (block.kind) {
    case "code":
    case "html":
      return 32 * fontScale
    case "frontmatter":
      return 24 * fontScale
    case "heading":
      return 36 * fontScale
    case "list":
      return 12 * fontScale
    case "table":
      return splitTextLines(block.markdown).length * 8 * fontScale
    case "thematicBreak":
      return 28 * fontScale
    default:
      return 0
  }
}

function prepareWithSegmentsSafe(
  text: string,
  font: string,
  options?: Parameters<typeof prepareWithSegments>[2]
) {
  try {
    return prepareWithSegments(text, font, options)
  } catch {
    return null
  }
}

function measureLineStatsSafe(
  prepared: PreparedTextWithSegments,
  width: number,
  fallbackText: string
) {
  try {
    return measureLineStats(prepared, width)
  } catch {
    return estimatePretextMarkdownLineStats(fallbackText, width)
  }
}

// Browser-layout line count for one text run: prepare + measure via Pretext,
// falling back to a character-width estimate when measurement is unavailable.
function measureWrappedLineCount(
  text: string,
  font: string,
  measureWidth: number
) {
  const safeText = text || " "
  const prepared = prepareWithSegmentsSafe(safeText, font, {
    whiteSpace: "pre-wrap",
  })
  const stats = prepared
    ? measureLineStatsSafe(prepared, measureWidth, safeText)
    : estimatePretextMarkdownLineStats(safeText, measureWidth)
  return Math.max(1, stats.lineCount)
}

// Conservative wrapped-line estimate for hostile blocks/chunks, where the
// longest line drives an unmeasured width-based wrap count.
function estimateWrappedLineCount(
  text: string,
  fontScale: number,
  textWidth: number
) {
  const lines = splitTextLines(text || " ")
  const longestLineLength = lines.reduce(
    (maxLength, line) => Math.max(maxLength, line.length),
    1
  )
  return Math.max(
    lines.length,
    Math.ceil(
      (longestLineLength * APPROX_CHAR_WIDTH_PX * fontScale) /
        Math.max(1, textWidth)
    )
  )
}

function estimatePretextMarkdownLineStats(text: string, width: number) {
  const columns = Math.max(1, Math.floor(width / APPROX_CHAR_WIDTH_PX))
  const lines = splitTextLines(text || " ")
  const lineCount = lines.reduce(
    (sum, line) => sum + Math.max(1, Math.ceil((line || " ").length / columns)),
    0
  )
  return { lineCount }
}

"use client"

import { marked, type Token } from "marked"

export type PretextMarkdownTokenKind =
  | "code"
  | "comment"
  | "definition"
  | "heading"
  | "hr"
  | "html"
  | "list"
  | "paragraph"
  | "space"
  | "table"
  | "other"

export interface PretextMarkdownToken {
  isOrderedList?: boolean
  listStart?: number
  kind: PretextMarkdownTokenKind
  raw: string
  text: string
}

export interface PretextMarkdownParser {
  parse(markdown: string): PretextMarkdownToken[]
}

export const markedPretextMarkdownParser: PretextMarkdownParser = {
  parse(markdown) {
    return marked
      .lexer(markdown, { gfm: true })
      .map((token) => normalizePretextMarkdownToken(token))
  },
}

export function parsePretextMarkdownTokens(markdown: string) {
  return markedPretextMarkdownParser.parse(markdown)
}

function normalizePretextMarkdownToken(token: Token): PretextMarkdownToken {
  return {
    isOrderedList: readPretextMarkdownListOrdered(token),
    kind: normalizePretextMarkdownTokenKind(token),
    listStart: readPretextMarkdownListStart(token),
    raw: token.raw ?? "",
    text: "text" in token && typeof token.text === "string" ? token.text : "",
  }
}

function readPretextMarkdownListOrdered(token: Token) {
  return token.type === "list" ? token.ordered : undefined
}

function readPretextMarkdownListStart(token: Token) {
  return token.type === "list" && token.ordered && token.start !== ""
    ? Number(token.start)
    : undefined
}

function normalizePretextMarkdownTokenKind(token: Token): PretextMarkdownTokenKind {
  if (isMarkdownFootnoteDefinition(token.raw ?? "")) return "definition"

  switch (token.type) {
    case "code":
      return "code"
    case "def":
      return "definition"
    case "html":
      return isMarkdownHtmlComment(token.raw ?? "") ? "comment" : "html"
    case "heading":
    case "hr":
    case "list":
    case "paragraph":
    case "space":
    case "table":
      return token.type
    default:
      return "other"
  }
}

function isMarkdownHtmlComment(raw: string) {
  return /^<!--[\s\S]*-->$/.test(raw.trim())
}

function isMarkdownFootnoteDefinition(raw: string) {
  return /^\[\^[^\]\r\n]+\]:[ \t]?/u.test(raw.trimStart())
}

"use client"

import type { Options as ReactMarkdownOptions } from "react-markdown"
import rehypeKatex from "rehype-katex"
import rehypePrettyCode from "rehype-pretty-code"
import rehypeRaw from "rehype-raw"
import rehypeSanitize from "rehype-sanitize"
import remarkBreaks from "remark-breaks"
import remarkDirective from "remark-directive"
import remarkGemoji from "remark-gemoji"
import remarkGfm from "remark-gfm"
import remarkMath from "remark-math"
import remarkSmartypants from "remark-smartypants"
import { visit } from "unist-util-visit"

import {
  ALERT_LABELS,
  CALLOUT_LABELS,
  isPretextComponentKind,
  normalizePretextCalloutKind,
  parsePretextComponentProps,
  remarkPretextComponentDirectives,
  remarkPretextComponentMarkdown,
  type AlertKind,
  type CalloutKind,
  type PretextComponent,
  type PretextComponentFallback,
} from "./pretext-markdown-components"
import {
  createPretextMarkdownSanitizeSchema,
  PRETEXT_MARKDOWN_KATEX_OPTIONS,
} from "./pretext-markdown-sanitize"

type MarkdownPluginList = NonNullable<ReactMarkdownOptions["remarkPlugins"]>

export const PRETEXT_MARKDOWN_REHYPE_PLUGINS: MarkdownPluginList = [
  rehypeRaw,
  rehypePretextMarkdownInputPolicy,
  rehypePretextMarkdownCodeMeta,
  [rehypeSanitize, createPretextMarkdownSanitizeSchema()],
  [rehypeKatex, PRETEXT_MARKDOWN_KATEX_OPTIONS],
  [
    rehypePrettyCode,
    {
      keepBackground: false,
      theme: {
        dark: "github-dark",
        light: "github-light-default",
      },
    },
  ],
]

export const PRETEXT_MARKDOWN_SYNC_REHYPE_PLUGINS: MarkdownPluginList = [
  rehypeRaw,
  rehypePretextMarkdownInputPolicy,
  rehypePretextMarkdownCodeMeta,
  [rehypeSanitize, createPretextMarkdownSanitizeSchema()],
  [rehypeKatex, PRETEXT_MARKDOWN_KATEX_OPTIONS],
]

export function createPretextMarkdownRemarkPlugins(
  headingIds: readonly string[]
): MarkdownPluginList {
  return [
    remarkDirective,
    remarkPretextHeadingIds(headingIds),
    remarkPretextCodeMeta,
    remarkPretextStripRawInternalMetadata,
    remarkPretextComponentMarkdown,
    remarkPretextDefinitionLists,
    remarkSmartypants,
    remarkPretextDirectiveCallouts,
    remarkPretextComponentDirectives,
    remarkPretextGithubAlerts,
    remarkPretextProseTransforms,
    remarkGemoji,
    remarkGfm,
    remarkBreaks,
    remarkMath,
  ]
}

function rehypePretextMarkdownInputPolicy() {
  return function transform(tree: unknown) {
    removeUnsafePretextMarkdownInputs(tree)
  }
}

function rehypePretextMarkdownCodeMeta() {
  return function transform(tree: unknown) {
    visit(tree as any, "element", (node: any) => {
      if (node.tagName !== "code") return
      if (typeof node.data?.meta !== "string") return
      node.properties = {
        ...node.properties,
        metastring: node.data.meta,
      }
    })
  }
}

function removeUnsafePretextMarkdownInputs(node: unknown) {
  if (!node || typeof node !== "object" || !("children" in node)) return

  const parent = node as { children?: unknown[] }
  if (!Array.isArray(parent.children)) return

  parent.children = parent.children.filter(
    (child) => !isUnsafePretextMarkdownInput(child)
  )
  for (const child of parent.children) {
    removeUnsafePretextMarkdownInputs(child)
  }
}

function isUnsafePretextMarkdownInput(node: unknown) {
  if (!node || typeof node !== "object") return false

  const element = node as {
    tagName?: string
    properties?: Record<string, unknown>
  }
  if (element.tagName !== "input") return false

  return !(
    element.properties?.type === "checkbox" &&
    element.properties.disabled === true
  )
}

// A hast element's `properties` bag, or null for non-element nodes.
function getNodeProperties(node: unknown): Record<string, unknown> | null {
  return node && typeof node === "object" && "properties" in node
    ? (node.properties as Record<string, unknown>)
    : null
}

// hast lowercases data attributes to camelCase; read either spelling.
function readDataProp(properties: Record<string, unknown>, attribute: string) {
  const camelCase = attribute.replace(/-([a-z])/g, (_, letter: string) =>
    letter.toUpperCase()
  )
  return properties[camelCase] ?? properties[attribute]
}

export function readPretextHeadingId(props: Record<string, unknown>) {
  const id = readDataProp(props, "data-pretext-heading-id")
  return typeof id === "string" ? id : undefined
}

export function readPretextAlertKind(node: unknown): AlertKind | null {
  const properties = getNodeProperties(node)
  const value = properties
    ? readDataProp(properties, "data-pretext-alert-kind")
    : null
  return typeof value === "string" && value in ALERT_LABELS
    ? (value as AlertKind)
    : null
}

export function readPretextCallout(
  node: unknown
): { kind: CalloutKind; title: string } | null {
  const properties = getNodeProperties(node)
  if (!properties) return null

  const kind = normalizePretextCalloutKind(
    readDataProp(properties, "data-pretext-callout-kind")
  )
  if (!kind) return null

  const title = readDataProp(properties, "data-pretext-callout-title")
  return {
    kind,
    title:
      typeof title === "string" && title.trim() ? title : CALLOUT_LABELS[kind],
  }
}

export function readPretextComponent(node: unknown): PretextComponent | null {
  const properties = getNodeProperties(node)
  if (!properties) return null

  const name = readDataProp(properties, "data-pretext-component-name")
  if (typeof name !== "string" || !isPretextComponentKind(name)) {
    return null
  }

  const serializedProps = readDataProp(
    properties,
    "data-pretext-component-props"
  )
  if (typeof serializedProps !== "string") return null

  try {
    const parsed = JSON.parse(serializedProps) as Record<string, unknown>
    const props = parsePretextComponentProps(name, parsed)
    if (!props) return null
    return {
      name,
      props,
    }
  } catch {
    return null
  }
}

export function readPretextComponentFallback(
  node: unknown
): PretextComponentFallback | null {
  const properties = getNodeProperties(node)
  if (!properties) return null

  const source = readDataProp(
    properties,
    "data-pretext-component-fallback-source"
  )
  if (typeof source !== "string" || !source.trim()) return null

  const componentName = readDataProp(
    properties,
    "data-pretext-component-fallback-name"
  )
  const reason = readDataProp(
    properties,
    "data-pretext-component-fallback-reason"
  )

  return {
    componentName:
      typeof componentName === "string" && componentName.trim()
        ? componentName
        : "Component",
    reason:
      typeof reason === "string" && reason.trim()
        ? reason
        : "Unsupported component syntax",
    source,
  }
}

function remarkPretextHeadingIds(headingIds: readonly string[]) {
  return function pretextHeadingIds() {
    return function transform(tree: unknown) {
      let index = 0
      visit(tree, "heading", (node: any) => {
        const id = headingIds[index]
        index += 1
        if (!id) return

        node.data = {
          ...node.data,
          hProperties: {
            ...node.data?.hProperties,
            id,
            dataPretextHeadingId: id,
          },
        }
      })
    }
  }
}

function remarkPretextCodeMeta() {
  return function transform(tree: unknown) {
    visit(tree, "code", (node: any) => {
      if (typeof node.meta !== "string" || !node.meta.trim()) return
      node.data = {
        ...node.data,
        hProperties: {
          ...node.data?.hProperties,
          metastring: node.meta,
        },
      }
    })
  }
}

function remarkPretextStripRawInternalMetadata() {
  return function transform(tree: unknown) {
    visit(tree, "html", (node: any) => {
      if (typeof node.value !== "string") return
      node.value = stripPretextInternalRawHtmlAttributes(node.value)
    })
  }
}

function stripPretextInternalRawHtmlAttributes(value: string) {
  return value.replace(
    /\s+(?:data-pretext-[\w:-]+|datapretext[\w:-]+)(?:\s*=\s*(?:"[^"]*"|'[^']*'|[^\s"'=<>`]+))?/gi,
    ""
  )
}

function remarkPretextDefinitionLists() {
  return function transform(tree: any) {
    if (!Array.isArray(tree?.children)) return

    tree.children = tree.children.map((node: any) => {
      if (node?.type !== "paragraph") return node
      return createPretextDefinitionListNode(node) ?? node
    })
  }
}

function createPretextDefinitionListNode(node: any) {
  const children = Array.isArray(node.children) ? node.children : []
  const firstChild = children[0]
  if (firstChild?.type !== "text" || typeof firstChild.value !== "string") {
    return null
  }

  const match = /^([^\n:][^\n]*)\n:[ \t]*/.exec(firstChild.value)
  const term = match?.[1]?.trim()
  if (!match || !term) return null

  if (children.length === 1) {
    const descriptions = parsePlainPretextDefinitionDescriptions(
      firstChild.value
    )
    if (descriptions?.term === term) {
      return createPretextDefinitionListHastNode({
        descriptions: descriptions.descriptions.map((description) => [
          { type: "text", value: description },
        ]),
        position: node.position,
        term,
      })
    }
  }

  const descriptionChildren = clonePretextInlineChildrenAfterTextOffset(
    children,
    match[0].length
  )
  if (!hasPretextDefinitionDescriptionContent(descriptionChildren)) return null

  return createPretextDefinitionListHastNode({
    descriptions: [descriptionChildren],
    position: node.position,
    term,
  })
}

function parsePlainPretextDefinitionDescriptions(value: string) {
  const lines = value.split("\n")
  const term = lines[0]?.trim()
  if (!term || term.startsWith(":") || lines.length < 2) return null

  const descriptions: string[] = []
  for (const line of lines.slice(1)) {
    const match = /^:[ \t]*(.*)$/.exec(line)
    if (!match) return null
    const description = match[1]?.trim()
    if (!description) return null
    descriptions.push(description)
  }

  return { descriptions, term }
}

function clonePretextInlineChildrenAfterTextOffset(
  children: readonly any[],
  offset: number
) {
  const clonedChildren: any[] = []
  let remainingOffset = offset

  for (const child of children) {
    if (child.type === "text" && typeof child.value === "string") {
      if (remainingOffset >= child.value.length) {
        remainingOffset -= child.value.length
        continue
      }

      clonedChildren.push({
        ...child,
        value: child.value.slice(remainingOffset),
      })
      remainingOffset = 0
      continue
    }

    if (remainingOffset > 0) return []
    clonedChildren.push(clonePretextMarkdownAstNode(child))
  }

  return clonedChildren
}

function clonePretextMarkdownAstNode<T>(node: T): T {
  if (!node || typeof node !== "object") return node
  if (Array.isArray(node)) {
    return node.map((item) => clonePretextMarkdownAstNode(item)) as T
  }

  const cloned: Record<string, unknown> = {}
  for (const [key, value] of Object.entries(node)) {
    cloned[key] = clonePretextMarkdownAstNode(value)
  }
  return cloned as T
}

function hasPretextDefinitionDescriptionContent(children: readonly any[]) {
  return children.some((child) => {
    if (child.type === "text") return Boolean(String(child.value ?? "").trim())
    return true
  })
}

function createPretextDefinitionListHastNode({
  descriptions,
  position,
  term,
}: {
  descriptions: readonly (readonly any[])[]
  position: unknown
  term: string
}) {
  return {
    type: "pretextDefinitionList",
    data: {
      hName: "dl",
      hProperties: {
        dataPretextDefinitionList: "",
      },
    },
    children: [
      {
        type: "pretextDefinitionTerm",
        data: {
          hName: "dt",
          hProperties: {
            dataPretextDefinitionTerm: "",
          },
        },
        children: [{ type: "text", value: term }],
      },
      ...descriptions.map((children) => ({
        type: "pretextDefinitionDescription",
        data: {
          hName: "dd",
          hProperties: {
            dataPretextDefinitionDescription: "",
          },
        },
        children,
      })),
    ],
    position,
  }
}

function remarkPretextGithubAlerts() {
  return function transform(tree: unknown) {
    visit(tree, "blockquote", (node: any) => {
      const paragraph = node.children?.[0]
      const firstChild = paragraph?.children?.[0]
      if (paragraph?.type !== "paragraph" || firstChild?.type !== "text") {
        return
      }

      const match = /^\[!(NOTE|TIP|IMPORTANT|WARNING|CAUTION)\]\s*/i.exec(
        firstChild.value
      )
      if (!match) return

      const kind = match[1]!.toLowerCase() as AlertKind
      firstChild.value = firstChild.value.slice(match[0].length)
      if (!firstChild.value) {
        paragraph.children.shift()
      }
      if (paragraph.children.length === 0) {
        node.children.shift()
      }
      node.data = {
        ...node.data,
        hProperties: {
          ...node.data?.hProperties,
          dataPretextAlertKind: kind,
        },
      }
    })
  }
}

function remarkPretextDirectiveCallouts() {
  return function transform(tree: unknown) {
    visit(tree as any, ["containerDirective", "leafDirective"], (node: any) => {
      const kind = normalizePretextCalloutKind(node.name)
      if (!kind) return

      const title =
        typeof node.attributes?.title === "string" &&
        node.attributes.title.trim()
          ? node.attributes.title
          : CALLOUT_LABELS[kind]

      node.data = {
        ...node.data,
        hName: "div",
        hProperties: {
          ...node.data?.hProperties,
          dataPretextCalloutKind: kind,
          dataPretextCalloutTitle: title,
        },
      }
    })
  }
}

function remarkPretextProseTransforms() {
  return function transform(tree: unknown) {
    visit(tree, "text", (node: any) => {
      if (node.data?.pretextSkipProseTransforms) return
      if (typeof node.value === "string") {
        node.value = transformMarkdownProseText(node.value)
      }
    })
  }
}

function transformMarkdownProseText(text: string) {
  return text
    .replace(/<->/g, "↔")
    .replace(/(?<!<)->/g, "→")
    .replace(/<-+/g, "←")
    .replace(/\b1\/2\b/g, "½")
    .replace(/\b1\/4\b/g, "¼")
    .replace(/\b3\/4\b/g, "¾")
}

export function pretextMarkdownChunkId({
  index,
  sourceStartLine,
}: {
  index: number
  sourceStartLine: number
}) {
  return `pretext-markdown-chunk-${index + 1}-${sourceStartLine}`
}

export function pretextMarkdownTableHeaderId(
  chunkId: string,
  tableIndex: number,
  columnIndex: number
) {
  return `${chunkId}-table-${tableIndex}-column-${columnIndex}`
}

export function patchPretextMarkdownChunkTables({
  chunkId,
  root,
}: {
  chunkId: string
  root: HTMLElement | null
}) {
  if (!root) return

  root
    .querySelectorAll<HTMLTableElement>("table[data-pretext-markdown-table]")
    .forEach((table, tableIndex) => {
      const headers = Array.from(table.querySelectorAll("thead th"))
      const rows = Array.from(table.rows)
      const columnCount = Math.max(
        0,
        ...rows.map((row) =>
          Array.from(row.cells).reduce(
            (count, cell) => count + Math.max(1, cell.colSpan || 1),
            0
          )
        )
      )

      table.setAttribute("aria-rowcount", String(rows.length))
      table.setAttribute("aria-colcount", String(columnCount))

      rows.forEach((row, rowIndex) => {
        row.setAttribute("aria-rowindex", String(rowIndex + 1))
        row.setAttribute("data-pretext-table-row-index", String(rowIndex + 1))

        let columnIndex = 1
        Array.from(row.cells).forEach((cell) => {
          cell.setAttribute("aria-colindex", String(columnIndex))
          cell.setAttribute(
            "data-pretext-table-column-index",
            String(columnIndex)
          )
          columnIndex += Math.max(1, cell.colSpan || 1)
        })
      })

      headers.forEach((header, columnIndex) => {
        header.id = pretextMarkdownTableHeaderId(
          chunkId,
          tableIndex,
          columnIndex
        )
        header.setAttribute("scope", "col")
      })

      table.querySelectorAll("tbody tr").forEach((row) => {
        Array.from(row.querySelectorAll<HTMLTableCellElement>("td")).forEach(
          (cell, columnIndex) => {
            const header = headers[columnIndex]
            if (header) cell.headers = header.id
          }
        )
      })
    })
}

"use client"

import type {
  PretextMarkdownChunk,
  PretextMarkdownLineRange,
} from "./pretext-markdown-document-model"
import type { PretextMarkdownChunkFrame } from "./pretext-markdown-layout"

export interface PretextMarkdownScrollAnchor {
  chunkIndex: number
  offsetWithinChunkPx: number
}

export function getPretextMarkdownVisibleChunkFrames({
  frames,
  overscanPx,
  scrollTop,
  viewportHeight,
}: {
  frames: readonly PretextMarkdownChunkFrame[]
  overscanPx: number
  scrollTop: number
  viewportHeight: number
}) {
  if (!frames.length) return []

  const minY = Math.max(0, scrollTop - overscanPx)
  const maxY = scrollTop + viewportHeight + overscanPx
  const start = firstChunkWithBottomAfter(frames, minY)
  const end = firstChunkWithTopAtOrAfter(frames, maxY)
  return frames.slice(start, Math.max(start, end))
}

export function getPretextMarkdownFrameScrollAnchor({
  frames,
  scrollTop,
}: {
  frames: readonly PretextMarkdownChunkFrame[]
  scrollTop: number
}): PretextMarkdownScrollAnchor | null {
  if (!frames.length) return null

  const chunkIndex = Math.min(
    firstChunkWithBottomAfter(frames, scrollTop),
    frames.length - 1
  )
  const chunk = frames[chunkIndex]
  if (!chunk) return null

  return {
    chunkIndex: chunk.index,
    offsetWithinChunkPx: Math.max(0, scrollTop - chunk.top),
  }
}

export function resolvePretextMarkdownScrollAnchor({
  anchor,
  frames,
}: {
  anchor: PretextMarkdownScrollAnchor
  frames: readonly PretextMarkdownChunkFrame[]
}) {
  const frame = frames.find((item) => item.index === anchor.chunkIndex)
  if (!frame) return null

  return Math.max(
    0,
    frame.top +
      Math.min(anchor.offsetWithinChunkPx, Math.max(0, frame.height - 1))
  )
}

export function getPretextMarkdownScrollTopForLineRange({
  chunks,
  frames,
  range,
  viewportHeight,
}: {
  chunks: readonly Pick<
    PretextMarkdownChunk,
    "index" | "sourceEndLine" | "sourceStartLine"
  >[]
  frames: readonly PretextMarkdownChunkFrame[]
  range: PretextMarkdownLineRange | null
  viewportHeight: number
}) {
  if (!range) return null

  const chunk =
    chunks.find(
      (item) =>
        item.sourceStartLine <= range.start && item.sourceEndLine >= range.start
    ) ?? chunks[0]
  const targetFrame = chunk
    ? frames.find((frame) => frame.index === chunk.index)
    : null
  if (!targetFrame) return null

  if (targetFrame.height > viewportHeight) {
    const lineOffset = estimatePretextMarkdownLineOffsetWithinFrame({
      frame: targetFrame,
      sourceLine: range.start,
    })
    const viewportLead = Math.min(viewportHeight * 0.25, targetFrame.height / 2)
    const maxScrollTop = Math.max(
      targetFrame.top,
      targetFrame.bottom - Math.min(viewportHeight, targetFrame.height)
    )
    return Math.max(
      0,
      Math.min(maxScrollTop, targetFrame.top + lineOffset - viewportLead)
    )
  }

  return Math.max(
    0,
    targetFrame.top - (viewportHeight - targetFrame.height) / 2
  )
}

export function getPretextMarkdownSourceLineForScrollTop({
  chunks,
  frames,
  scrollTop,
}: {
  chunks: readonly Pick<
    PretextMarkdownChunk,
    "index" | "sourceEndLine" | "sourceStartLine"
  >[]
  frames: readonly PretextMarkdownChunkFrame[]
  scrollTop: number
}) {
  if (!frames.length) return 1

  const chunkIndex = Math.min(
    firstChunkWithBottomAfter(frames, scrollTop),
    frames.length - 1
  )
  const frame = frames[chunkIndex]
  if (!frame) return 1

  const chunk = chunks.find((item) => item.index === frame.index)
  if (!chunk) return frame.sourceStartLine

  const lineCount = Math.max(1, chunk.sourceEndLine - chunk.sourceStartLine + 1)
  const offsetRatio =
    frame.height <= 0
      ? 0
      : Math.max(0, Math.min(1, (scrollTop - frame.top) / frame.height))
  const lineOffset = Math.min(
    lineCount - 1,
    Math.floor(offsetRatio * lineCount)
  )
  return chunk.sourceStartLine + lineOffset
}

export function markdownChunkIntersectsLineRange({
  chunk,
  range,
}: {
  chunk: Pick<PretextMarkdownChunk, "sourceEndLine" | "sourceStartLine">
  range: PretextMarkdownLineRange | null
}) {
  if (!range) return false
  return (
    chunk.sourceStartLine <= range.end && chunk.sourceEndLine >= range.start
  )
}

function firstChunkWithBottomAfter(
  frames: readonly PretextMarkdownChunkFrame[],
  y: number
) {
  let low = 0
  let high = frames.length
  while (low < high) {
    const mid = Math.floor((low + high) / 2)
    if (frames[mid]!.bottom > y) high = mid
    else low = mid + 1
  }
  return low
}

function estimatePretextMarkdownLineOffsetWithinFrame({
  frame,
  sourceLine,
}: {
  frame: Pick<
    PretextMarkdownChunkFrame,
    "height" | "sourceEndLine" | "sourceStartLine"
  >
  sourceLine: number
}) {
  const lineCount = Math.max(1, frame.sourceEndLine - frame.sourceStartLine + 1)
  const lineIndex = Math.min(
    lineCount - 1,
    Math.max(0, sourceLine - frame.sourceStartLine)
  )
  return (lineIndex / lineCount) * frame.height
}

function firstChunkWithTopAtOrAfter(
  frames: readonly PretextMarkdownChunkFrame[],
  y: number
) {
  let low = 0
  let high = frames.length
  while (low < high) {
    const mid = Math.floor((low + high) / 2)
    if (frames[mid]!.top >= y) high = mid
    else low = mid + 1
  }
  return low
}

