function renderBasicMermaidMindMapDiagram(
  lines: readonly string[]
): { status: "ready"; svg: string } | null {
  if (!/^mindmap$/i.test(lines[0] ?? "")) return null

  const nodes = lines
    .slice(1)
    .map(readPretextMarkdownMindMapLabel)
    .filter(Boolean)
  if (nodes.length === 0) return null

  const [root = "Mind map", ...children] = nodes
  const width = 560
  const rowHeight = 38
  const height = Math.max(170, 92 + children.length * rowHeight)
  const rootX = 136
  const rootY = height / 2
  const childSvg = children
    .map((child, index) => {
      const y =
        children.length === 1
          ? rootY
          : 48 + index * ((height - 96) / Math.max(1, children.length - 1))
      return `<g><path d="M ${rootX + 72} ${rootY} C ${rootX + 130} ${rootY}, 300 ${y}, 352 ${y}" fill="none" stroke="currentColor" stroke-width="1.4" opacity="0.42" /><rect x="352" y="${y - 18}" width="146" height="36" rx="18" fill="var(--card)" stroke="currentColor" opacity="0.9" /><text x="425" y="${y + 5}" text-anchor="middle" font-size="13" fill="currentColor">${escapePretextMarkdownSvg(child)}</text></g>`
    })
    .join("")

  return {
    status: "ready",
    svg: buildPretextMarkdownDiagramSvg({
      body: `<rect x="${rootX - 72}" y="${rootY - 22}" width="144" height="44" rx="22" fill="var(--card)" stroke="currentColor" opacity="0.95" /><text x="${rootX}" y="${rootY + 5}" text-anchor="middle" font-size="13" font-weight="600" fill="currentColor">${escapePretextMarkdownSvg(root)}</text>${childSvg}`,
      height,
      kind: "mindmap",
      width,
    }),
  }
}

function readPretextMarkdownMindMapLabel(line: string) {
  const rootCircle = line.match(/^[A-Za-z0-9_.-]*\(\((.+)\)\)$/)
  if (rootCircle) return rootCircle[1]!.trim()

  return line
    .trim()
    .replace(/^[A-Za-z0-9_.-]+\(\((.+)\)\)$/, "$1")
    .replace(/\)+$/, "")
    .replace(/\(\(/g, "")
    .replace(/\)\)/g, "")
    .trim()
}

function renderBasicMermaidQuadrantDiagram(
  lines: readonly string[]
): { status: "ready"; svg: string } | null {
  if (!/^quadrantChart$/i.test(lines[0] ?? "")) return null

  const quadrants = new Map<number, string>()
  const points: Array<{ label: string; x: number; y: number }> = []
  let xStart = "Low X"
  let xEnd = "High X"
  let yStart = "Low Y"
  let yEnd = "High Y"

  for (const line of lines.slice(1)) {
    if (/^title\s+/i.test(line)) continue

    const xAxis = line.match(/^x-axis\s+(.+?)\s+-->\s+(.+)$/i)
    if (xAxis) {
      xStart = xAxis[1]!.trim()
      xEnd = xAxis[2]!.trim()
      continue
    }

    const yAxis = line.match(/^y-axis\s+(.+?)\s+-->\s+(.+)$/i)
    if (yAxis) {
      yStart = yAxis[1]!.trim()
      yEnd = yAxis[2]!.trim()
      continue
    }

    const quadrant = line.match(/^quadrant-(\d+)\s+(.+)$/i)
    if (quadrant) {
      quadrants.set(Number(quadrant[1]), quadrant[2]!.trim())
      continue
    }

    const point = line.match(
      /^(.+):\s*\[\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*\]$/
    )
    if (!point) continue
    points.push({
      label: point[1]!.trim(),
      x: clampPretextMarkdownUnitInterval(Number(point[2])),
      y: clampPretextMarkdownUnitInterval(Number(point[3])),
    })
  }

  if (points.length === 0) return null

  const width = 560
  const height = 360
  const left = 82
  const top = 42
  const plotWidth = 380
  const plotHeight = 250
  const pointSvg = points
    .map((point) => {
      const x = left + point.x * plotWidth
      const y = top + (1 - point.y) * plotHeight
      return `<g><circle cx="${x}" cy="${y}" r="6" fill="var(--card)" stroke="currentColor" stroke-width="2" /><text x="${x + 10}" y="${y - 8}" font-size="12" fill="currentColor">${escapePretextMarkdownSvg(point.label)}</text></g>`
    })
    .join("")
  const quadrantSvg = [
    { label: quadrants.get(2) ?? "Quadrant 2", x: left + 16, y: top + 24 },
    {
      label: quadrants.get(1) ?? "Quadrant 1",
      x: left + plotWidth / 2 + 16,
      y: top + 24,
    },
    {
      label: quadrants.get(3) ?? "Quadrant 3",
      x: left + 16,
      y: top + plotHeight / 2 + 24,
    },
    {
      label: quadrants.get(4) ?? "Quadrant 4",
      x: left + plotWidth / 2 + 16,
      y: top + plotHeight / 2 + 24,
    },
  ]
    .map(
      (quadrant) =>
        `<text x="${quadrant.x}" y="${quadrant.y}" font-size="12" fill="currentColor" opacity="0.48">${escapePretextMarkdownSvg(quadrant.label)}</text>`
    )
    .join("")

  return {
    status: "ready",
    svg: buildPretextMarkdownDiagramSvg({
      body: `<rect x="${left}" y="${top}" width="${plotWidth}" height="${plotHeight}" fill="var(--card)" opacity="0.35" /><line x1="${left + plotWidth / 2}" y1="${top}" x2="${left + plotWidth / 2}" y2="${top + plotHeight}" stroke="currentColor" opacity="0.22" /><line x1="${left}" y1="${top + plotHeight / 2}" x2="${left + plotWidth}" y2="${top + plotHeight / 2}" stroke="currentColor" opacity="0.22" /><rect x="${left}" y="${top}" width="${plotWidth}" height="${plotHeight}" fill="none" stroke="currentColor" opacity="0.45" />${quadrantSvg}${pointSvg}<text x="${left}" y="${height - 34}" font-size="12" fill="currentColor" opacity="0.72">${escapePretextMarkdownSvg(xStart)}</text><text x="${left + plotWidth}" y="${height - 34}" text-anchor="end" font-size="12" fill="currentColor" opacity="0.72">${escapePretextMarkdownSvg(xEnd)}</text><text x="24" y="${top + plotHeight}" font-size="12" fill="currentColor" opacity="0.72">${escapePretextMarkdownSvg(yStart)}</text><text x="24" y="${top + 10}" font-size="12" fill="currentColor" opacity="0.72">${escapePretextMarkdownSvg(yEnd)}</text>`,
      height,
      kind: "quadrantChart",
      width,
    }),
  }
}

function renderBasicMermaidRequirementDiagram(
  lines: readonly string[]
): { status: "ready"; svg: string } | null {
  if (!/^requirementDiagram$/i.test(lines[0] ?? "")) return null

  const requirements = new Map<string, string>()
  const elements = new Map<string, string>()
  const relationships: Array<{ from: string; label: string; to: string }> = []
  let currentBlock: {
    id: string
    kind: "element" | "requirement"
    label: string
  } | null = null

  const commitCurrentBlock = () => {
    if (!currentBlock) return
    const target = currentBlock.kind === "requirement" ? requirements : elements
    target.set(currentBlock.id, currentBlock.label || currentBlock.id)
    currentBlock = null
  }

  for (const line of lines.slice(1)) {
    const block = line.match(
      /^(requirement|element)\s+([A-Za-z0-9_.-]+)\s*\{$/i
    )
    if (block) {
      commitCurrentBlock()
      currentBlock = {
        id: block[2]!,
        kind:
          block[1]!.toLowerCase() === "requirement" ? "requirement" : "element",
        label: block[2]!,
      }
      continue
    }

    if (line === "}") {
      commitCurrentBlock()
      continue
    }

    const text = line.match(/^(?:text|type)\s*:\s*(.+)$/i)
    if (text && currentBlock) {
      currentBlock.label = text[1]!.replace(/^"|"$/g, "").trim()
      continue
    }

    const relationship = line.match(
      /^([A-Za-z0-9_.-]+)\s+-\s+([A-Za-z]+)\s+->\s+([A-Za-z0-9_.-]+)$/i
    )
    if (relationship) {
      commitCurrentBlock()
      relationships.push({
        from: relationship[1]!,
        label: relationship[2]!,
        to: relationship[3]!,
      })
    }
  }
  commitCurrentBlock()

  for (const relationship of relationships) {
    if (
      !requirements.has(relationship.from) &&
      !elements.has(relationship.from)
    ) {
      elements.set(relationship.from, relationship.from)
    }
    if (!requirements.has(relationship.to) && !elements.has(relationship.to)) {
      requirements.set(relationship.to, relationship.to)
    }
  }

  if (requirements.size === 0 && elements.size === 0) return null

  const requirementIds = Array.from(requirements.keys())
  const elementIds = Array.from(elements.keys())
  const rowCount = Math.max(requirementIds.length, elementIds.length, 1)
  const width = 620
  const rowHeight = 66
  const height = rowCount * rowHeight + 64
  const leftX = 46
  const rightX = 382
  const nodeWidth = 192
  const nodeHeight = 44
  const position = new Map<string, { x: number; y: number }>()

  const requirementSvg = requirementIds
    .map((id, index) => {
      const y = 42 + index * rowHeight
      position.set(id, { x: rightX, y })
      return `<g><rect x="${rightX}" y="${y}" width="${nodeWidth}" height="${nodeHeight}" rx="8" fill="var(--card)" stroke="currentColor" opacity="0.92" /><text x="${rightX + 12}" y="${y + 18}" font-size="11" fill="currentColor" opacity="0.62">requirement</text><text x="${rightX + 12}" y="${y + 34}" font-size="13" fill="currentColor">${escapePretextMarkdownSvg(shortenPretextMarkdownSvgLabel(requirements.get(id) ?? id, 36))}</text></g>`
    })
    .join("")
  const elementSvg = elementIds
    .map((id, index) => {
      const y = 42 + index * rowHeight
      position.set(id, { x: leftX, y })
      return `<g><rect x="${leftX}" y="${y}" width="${nodeWidth}" height="${nodeHeight}" rx="8" fill="var(--card)" stroke="currentColor" opacity="0.72" /><text x="${leftX + 12}" y="${y + 18}" font-size="11" fill="currentColor" opacity="0.62">element</text><text x="${leftX + 12}" y="${y + 34}" font-size="13" fill="currentColor">${escapePretextMarkdownSvg(shortenPretextMarkdownSvgLabel(elements.get(id) ?? id, 26))}</text></g>`
    })
    .join("")
  const relationshipSvg = relationships
    .map((relationship) => {
      const from = position.get(relationship.from)
      const to = position.get(relationship.to)
      if (!from || !to) return ""
      const x1 = from.x < to.x ? from.x + nodeWidth : from.x
      const x2 = from.x < to.x ? to.x : to.x + nodeWidth
      const y1 = from.y + nodeHeight / 2
      const y2 = to.y + nodeHeight / 2
      return `<g><line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="currentColor" stroke-width="1.4" opacity="0.48" /><text x="${(x1 + x2) / 2}" y="${(y1 + y2) / 2 - 8}" text-anchor="middle" font-size="11" fill="currentColor" opacity="0.72">${escapePretextMarkdownSvg(relationship.label)}</text></g>`
    })
    .join("")

  return {
    status: "ready",
    svg: buildPretextMarkdownDiagramSvg({
      body: `${relationshipSvg}${elementSvg}${requirementSvg}`,
      height,
      kind: "requirementDiagram",
      width,
    }),
  }
}

function renderBasicMermaidXyChartDiagram(
  lines: readonly string[]
): { status: "ready"; svg: string } | null {
  if (!/^xychart(?:-beta)?$/i.test(lines[0] ?? "")) return null

  const xLabels: string[] = []
  const series: Array<{ kind: "bar" | "line"; values: number[] }> = []
  for (const line of lines.slice(1)) {
    const xAxis = line.match(/^x-axis\s+\[(.*)\]$/i)
    if (xAxis) {
      xLabels.push(
        ...xAxis[1]!
          .split(",")
          .map((label) => label.trim().replace(/^"|"$/g, ""))
          .filter(Boolean)
      )
      continue
    }

    const values = line.match(/^(bar|line)\s*\[(.*)\]$/i)
    if (values) {
      series.push({
        kind: values[1]!.toLowerCase() === "bar" ? "bar" : "line",
        values: readPretextMarkdownNumberList(values[2]!),
      })
    }
  }

  const valueList = series.flatMap((entry) => entry.values)
  if (series.length === 0 || valueList.length === 0) return null

  const minValue = Math.min(0, ...valueList)
  const maxValue = Math.max(...valueList)
  const span = maxValue - minValue || 1
  const maxLength = Math.max(...series.map((entry) => entry.values.length))
  const width = 600
  const height = 330
  const left = 64
  const top = 34
  const chartWidth = 460
  const chartHeight = 220
  const readX = (index: number) =>
    left +
    (maxLength <= 1 ? chartWidth / 2 : (index / (maxLength - 1)) * chartWidth)
  const readY = (value: number) =>
    top + chartHeight - ((value - minValue) / span) * chartHeight
  const barSeries = series.filter((entry) => entry.kind === "bar")
  const lineSeries = series.filter((entry) => entry.kind === "line")
  const barWidth = Math.max(14, chartWidth / Math.max(1, maxLength) / 2.8)
  const barSvg = barSeries
    .flatMap((entry, seriesIndex) =>
      entry.values.map((value, index) => {
        const x = readX(index) - barWidth / 2 + seriesIndex * (barWidth + 3)
        const y = readY(value)
        return `<rect x="${x}" y="${y}" width="${barWidth}" height="${top + chartHeight - y}" rx="3" fill="currentColor" opacity="${0.34 + seriesIndex * 0.16}" />`
      })
    )
    .join("")
  const lineSvg = lineSeries
    .map((entry, seriesIndex) => {
      const points = entry.values
        .map((value, index) => `${readX(index)},${readY(value)}`)
        .join(" ")
      const circles = entry.values
        .map(
          (value, index) =>
            `<circle cx="${readX(index)}" cy="${readY(value)}" r="4" fill="var(--card)" stroke="currentColor" stroke-width="1.8" />`
        )
        .join("")
      return `<g opacity="${0.78 - seriesIndex * 0.12}"><polyline points="${points}" fill="none" stroke="currentColor" stroke-width="2" />${circles}</g>`
    })
    .join("")
  const xLabelSvg = Array.from({ length: maxLength }, (_, index) => {
    const label = xLabels[index] ?? String(index + 1)
    return `<text x="${readX(index)}" y="${height - 42}" text-anchor="middle" font-size="11" fill="currentColor" opacity="0.68">${escapePretextMarkdownSvg(shortenPretextMarkdownSvgLabel(label, 10))}</text>`
  }).join("")

  return {
    status: "ready",
    svg: buildPretextMarkdownDiagramSvg({
      body: `<line x1="${left}" y1="${top}" x2="${left}" y2="${top + chartHeight}" stroke="currentColor" opacity="0.45" /><line x1="${left}" y1="${top + chartHeight}" x2="${left + chartWidth}" y2="${top + chartHeight}" stroke="currentColor" opacity="0.45" /><text x="${left - 10}" y="${top + 5}" text-anchor="end" font-size="11" fill="currentColor" opacity="0.72">${escapePretextMarkdownSvg(formatPretextMarkdownPieNumber(maxValue))}</text><text x="${left - 10}" y="${top + chartHeight}" text-anchor="end" font-size="11" fill="currentColor" opacity="0.72">${escapePretextMarkdownSvg(formatPretextMarkdownPieNumber(minValue))}</text>${barSvg}${lineSvg}${xLabelSvg}`,
      height,
      kind: "xychart",
      width,
    }),
  }
}

function clampPretextMarkdownUnitInterval(value: number) {
  if (!Number.isFinite(value)) return 0
  return Math.max(0, Math.min(1, value))
}

function readPretextMarkdownNumberList(value: string) {
  return value
    .split(",")
    .map((part) => Number(part.trim()))
    .filter((part) => Number.isFinite(part))
}

function shortenPretextMarkdownSvgLabel(value: string, maxLength: number) {
  return value.length > maxLength
    ? `${value.slice(0, maxLength - 1)}...`
    : value
}

function renderBasicMermaidSankeyDiagram(
  lines: readonly string[]
): { status: "ready"; svg: string } | null {
  if (!/^sankey-beta$/i.test(lines[0] ?? "")) return null

  const flows: Array<{ from: string; to: string; value: number }> = []
  const leftNodes = new Map<string, number>()
  const rightNodes = new Map<string, number>()
  for (const line of lines.slice(1)) {
    const flow = line.match(/^(.+?)\s*,\s*(.+?)\s*,\s*(-?\d+(?:\.\d+)?)$/)
    if (!flow) continue
    const value = Number(flow[3])
    if (!(value > 0)) continue
    const from = flow[1]!.trim()
    const to = flow[2]!.trim()
    flows.push({ from, to, value })
    leftNodes.set(from, (leftNodes.get(from) ?? 0) + value)
    rightNodes.set(to, (rightNodes.get(to) ?? 0) + value)
  }

  if (flows.length === 0) return null

  const width = 620
  const leftX = 74
  const rightX = 418
  const nodeWidth = 150
  const rowHeight = 54
  const leftNodeNames = Array.from(leftNodes.keys())
  const rightNodeNames = Array.from(rightNodes.keys())
  const rowCount = Math.max(leftNodeNames.length, rightNodeNames.length)
  const height = rowCount * rowHeight + 76
  const leftPosition = new Map(
    leftNodeNames.map((node, index) => [node, 42 + index * rowHeight] as const)
  )
  const rightPosition = new Map(
    rightNodeNames.map((node, index) => [node, 42 + index * rowHeight] as const)
  )
  const maxValue = Math.max(...flows.map((flow) => flow.value))
  const flowSvg = flows
    .map((flow) => {
      const y1 = (leftPosition.get(flow.from) ?? 42) + 18
      const y2 = (rightPosition.get(flow.to) ?? 42) + 18
      const strokeWidth = 2 + (flow.value / maxValue) * 10
      return `<path d="M ${leftX + nodeWidth} ${y1} C ${leftX + nodeWidth + 92} ${y1}, ${rightX - 92} ${y2}, ${rightX} ${y2}" fill="none" stroke="currentColor" stroke-width="${strokeWidth}" opacity="0.28" />`
    })
    .join("")
  const leftNodeSvg = leftNodeNames
    .map((node) => {
      const y = leftPosition.get(node)!
      return `<g><rect x="${leftX}" y="${y}" width="${nodeWidth}" height="36" rx="8" fill="var(--card)" stroke="currentColor" opacity="0.9" /><text x="${leftX + 12}" y="${y + 23}" font-size="13" fill="currentColor">${escapePretextMarkdownSvg(shortenPretextMarkdownSvgLabel(node, 20))}</text></g>`
    })
    .join("")
  const rightNodeSvg = rightNodeNames
    .map((node) => {
      const y = rightPosition.get(node)!
      return `<g><rect x="${rightX}" y="${y}" width="${nodeWidth}" height="36" rx="8" fill="var(--card)" stroke="currentColor" opacity="0.9" /><text x="${rightX + 12}" y="${y + 23}" font-size="13" fill="currentColor">${escapePretextMarkdownSvg(shortenPretextMarkdownSvgLabel(node, 20))}</text></g>`
    })
    .join("")

  return {
    status: "ready",
    svg: buildPretextMarkdownDiagramSvg({
      body: `${flowSvg}${leftNodeSvg}${rightNodeSvg}`,
      height,
      kind: "sankey",
      width,
    }),
  }
}

function renderBasicMermaidC4Diagram(
  lines: readonly string[]
): { status: "ready"; svg: string } | null {
  if (
    !/^C4(?:Context|Container|Component|Dynamic|Deployment)$/i.test(
      lines[0] ?? ""
    )
  ) {
    return null
  }

  const nodes = new Map<string, { kind: string; label: string }>()
  const relationships: Array<{ from: string; label: string; to: string }> = []
  for (const line of lines.slice(1)) {
    const node = line.match(
      /^(Person|Person_Ext|System|System_Ext|Container|ContainerDb|ContainerQueue|Container_Ext|Component|ComponentDb|ComponentQueue|Component_Ext|Boundary|System_Boundary|Container_Boundary|Enterprise_Boundary|Deployment_Node)\s*\(\s*([A-Za-z0-9_.-]+)\s*,\s*"([^"]+)"/i
    )
    if (node) {
      nodes.set(node[2]!, { kind: node[1]!, label: node[3]! })
      continue
    }

    const relationship = line.match(
      /^Rel(?:_[A-Za-z]+)?\s*\(\s*([A-Za-z0-9_.-]+)\s*,\s*([A-Za-z0-9_.-]+)\s*,\s*"([^"]*)"/i
    )
    if (!relationship) continue
    const from = relationship[1]!
    const to = relationship[2]!
    if (!nodes.has(from)) nodes.set(from, { kind: "Node", label: from })
    if (!nodes.has(to)) nodes.set(to, { kind: "Node", label: to })
    relationships.push({
      from,
      label: relationship[3]!,
      to,
    })
  }

  if (nodes.size === 0) return null

  const nodeIds = Array.from(nodes.keys())
  const nodeWidth = 150
  const nodeHeight = 50
  const columnGap = 86
  const rowGap = 70
  const columns = nodeIds.length > 2 ? 2 : nodeIds.length
  const rows = Math.ceil(nodeIds.length / columns)
  const width = Math.max(
    420,
    columns * nodeWidth + Math.max(0, columns - 1) * columnGap + 72
  )
  const height = rows * nodeHeight + Math.max(0, rows - 1) * rowGap + 72
  const gridWidth = columns * nodeWidth + Math.max(0, columns - 1) * columnGap
  const left = (width - gridWidth) / 2
  const positions = new Map(
    nodeIds.map((nodeId, index) => {
      const column = index % columns
      const row = Math.floor(index / columns)
      return [
        nodeId,
        {
          x: left + column * (nodeWidth + columnGap),
          y: 36 + row * (nodeHeight + rowGap),
        },
      ] as const
    })
  )
  const relationshipSvg = relationships
    .map((relationship) => {
      const from = positions.get(relationship.from)!
      const to = positions.get(relationship.to)!
      const x1 = from.x + nodeWidth / 2
      const y1 = from.y + nodeHeight / 2
      const x2 = to.x + nodeWidth / 2
      const y2 = to.y + nodeHeight / 2
      const label = relationship.label
        ? `<text x="${(x1 + x2) / 2}" y="${(y1 + y2) / 2 - 8}" text-anchor="middle" font-size="11" fill="currentColor" opacity="0.74">${escapePretextMarkdownSvg(shortenPretextMarkdownSvgLabel(relationship.label, 24))}</text>`
        : ""
      return `${label}<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="currentColor" stroke-width="1.5" opacity="0.52" />`
    })
    .join("")
  const nodeSvg = nodeIds
    .map((nodeId) => {
      const position = positions.get(nodeId)!
      const node = nodes.get(nodeId)!
      return `<g><rect x="${position.x}" y="${position.y}" width="${nodeWidth}" height="${nodeHeight}" rx="8" fill="var(--card)" stroke="currentColor" opacity="0.92" /><text x="${position.x + 12}" y="${position.y + 19}" font-size="11" fill="currentColor" opacity="0.62">${escapePretextMarkdownSvg(node.kind.replace(/_/g, " "))}</text><text x="${position.x + 12}" y="${position.y + 36}" font-size="13" fill="currentColor">${escapePretextMarkdownSvg(shortenPretextMarkdownSvgLabel(node.label, 20))}</text></g>`
    })
    .join("")

  return {
    status: "ready",
    svg: buildPretextMarkdownDiagramSvg({
      body: `${relationshipSvg}${nodeSvg}`,
      height,
      kind: "c4",
      width,
    }),
  }
}

function describePretextMarkdownPieSlicePath({
  centerX,
  centerY,
  endAngle,
  radius,
  startAngle,
}: {
  centerX: number
  centerY: number
  endAngle: number
  radius: number
  startAngle: number
}) {
  const start = readPretextMarkdownPolarPoint({
    angle: startAngle,
    centerX,
    centerY,
    radius,
  })
  const end = readPretextMarkdownPolarPoint({
    angle: endAngle,
    centerX,
    centerY,
    radius,
  })
  const largeArc = endAngle - startAngle > 180 ? 1 : 0
  return `M ${centerX} ${centerY} L ${start.x} ${start.y} A ${radius} ${radius} 0 ${largeArc} 1 ${end.x} ${end.y} Z`
}

function readPretextMarkdownPolarPoint({
  angle,
  centerX,
  centerY,
  radius,
}: {
  angle: number
  centerX: number
  centerY: number
  radius: number
}) {
  const radians = (angle * Math.PI) / 180
  return {
    x: Number((centerX + radius * Math.cos(radians)).toFixed(3)),
    y: Number((centerY + radius * Math.sin(radians)).toFixed(3)),
  }
}

function formatPretextMarkdownPieNumber(value: number) {
  return Number.isInteger(value)
    ? String(value)
    : String(Number(value.toFixed(3)))
}

function parsePretextMarkdownMermaidNode(value: string) {
  const trimmed = value.trim()
  const match =
    trimmed.match(/^([A-Za-z0-9_-]+)\s*\["(.+)"\]$/) ??
    trimmed.match(/^([A-Za-z0-9_-]+)\s*\[(.+)\]$/) ??
    trimmed.match(/^([A-Za-z0-9_-]+)\s*\((.+)\)$/)
  if (match) {
    return { id: match[1]!, label: match[2]!.trim() }
  }

  const id = trimmed.replace(/[^A-Za-z0-9_-].*$/, "")
  return { id: id || trimmed, label: id || trimmed }
}

/**
 * Shared `<svg>` scaffolding for the basic (fallback) renderers. Every basic
 * renderer emits the identical root element — only the `data-pretext-basic-mermaid`
 * kind, the dimensions, the optional `<defs>`, and the body markup differ.
 */
function buildPretextMarkdownDiagramSvg({
  body,
  defs = "",
  height,
  kind,
  width,
}: {
  body: string
  defs?: string
  height: number
  kind: string
  width: number
}) {
  return `<svg role="img" aria-label="Mermaid diagram" data-pretext-basic-mermaid="${kind}" viewBox="0 0 ${width} ${height}" width="100%" height="${height}" xmlns="http://www.w3.org/2000/svg">${defs}${body}</svg>`
}

/**
 * The arrow-head marker shared by the graph/sequence/state/class fallbacks. Only
 * the marker `id` (so each diagram references its own) and the opacity vary.
 */
function buildPretextMarkdownDiagramArrowDefs(id: string, opacity: number) {
  return `<defs><marker id="${id}" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 Z" fill="currentColor" opacity="${opacity}"/></marker></defs>`
}

function escapePretextMarkdownSvg(value: string) {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
}

"use client"

const URL_CONTROL_CHARACTER_PATTERN = /[\u0000-\u001F\u007F]/
const URL_SCHEME_PATTERN = /^([A-Za-z][A-Za-z0-9+.-]*):/
const URL_BACKSLASH_PATTERN = /[\\\uFE68\uFF3C\u2216]/
const URL_CONFUSABLE_DELIMITER_PATTERN =
  /[\u02D0\u0589\u05C3\u0703\u0704\u16EC\u1803\u1809\u205A\u2236\uA789\uFE13\uFE55\uFF1A\u2044\u2215\u2571\u27CB\u29F8\uFF0F]/
const ALLOWED_LINK_PROTOCOLS = new Set(["http", "https", "mailto"])

export function sanitizePretextMarkdownUrl(value: string) {
  const trimmed = value.trim()
  if (!trimmed) return ""
  if (URL_CONTROL_CHARACTER_PATTERN.test(trimmed)) return ""
  if (URL_BACKSLASH_PATTERN.test(trimmed)) return ""
  if (URL_CONFUSABLE_DELIMITER_PATTERN.test(trimmed)) return ""

  const decoded = decodePretextMarkdownUrl(trimmed).trim()
  if (!decoded || URL_CONTROL_CHARACTER_PATTERN.test(decoded)) return ""
  if (URL_BACKSLASH_PATTERN.test(decoded)) return ""
  if (URL_CONFUSABLE_DELIMITER_PATTERN.test(decoded)) return ""

  const decodedScheme = getPretextMarkdownUrlScheme(decoded)
  const rawScheme = getPretextMarkdownUrlScheme(trimmed)
  if (decodedScheme && decodedScheme !== rawScheme) return ""
  if (decodedScheme && !ALLOWED_LINK_PROTOCOLS.has(decodedScheme)) return ""

  if (trimmed.startsWith("#")) return trimmed
  if (trimmed.startsWith("/")) return trimmed.startsWith("//") ? "" : trimmed

  try {
    const url = new URL(trimmed, "https://retab.local")
    if (ALLOWED_LINK_PROTOCOLS.has(url.protocol.slice(0, -1))) {
      return trimmed
    }
  } catch {
    return ""
  }

  return ""
}

export function sanitizePretextMarkdownImageUrl(value: string) {
  const safeUrl = sanitizePretextMarkdownUrl(value)
  if (!safeUrl || safeUrl.startsWith("mailto:") || safeUrl.startsWith("#")) {
    return ""
  }
  if (isPretextMarkdownSvgResourceUrl(safeUrl)) return ""
  return safeUrl
}

export function sanitizePretextMarkdownMediaUrl(value: string) {
  // Image URLs already reject SVG resources, so media inherits that policy.
  return sanitizePretextMarkdownImageUrl(value)
}

function decodePretextMarkdownUrl(value: string) {
  try {
    return decodeURIComponent(value)
  } catch {
    return value
  }
}

function getPretextMarkdownUrlScheme(value: string) {
  return URL_SCHEME_PATTERN.exec(value)?.[1]?.toLowerCase() ?? null
}

export function isPretextMarkdownSvgResourceUrl(value: string) {
  const decoded = decodePretextMarkdownUrl(value).trim()

  try {
    const url = new URL(decoded, "https://retab.local")
    return /\.(?:svg|svgz)$/i.test(url.pathname)
  } catch {
    const pathname = decoded.split(/[?#]/, 1)[0] ?? decoded
    return /\.(?:svg|svgz)$/i.test(pathname)
  }
}

"use client"

import { visit } from "unist-util-visit"

export const ALERT_LABELS = {
  caution: "Caution:",
  important: "Important:",
  note: "Note:",
  tip: "Tip:",
  warning: "Warning:",
} as const

export type AlertKind = keyof typeof ALERT_LABELS

export const CALLOUT_LABELS = {
  caution: "Caution",
  danger: "Danger",
  important: "Important",
  info: "Info",
  note: "Note",
  tip: "Tip",
  warning: "Warning",
} as const

export type CalloutKind = keyof typeof CALLOUT_LABELS

type PretextComponentPropSchema = {
  type?: "boolean" | "display" | "number" | "string"
  values?: readonly string[]
}

type PretextComponentRegistryEntry = {
  directiveName: string
  props: Record<string, PretextComponentPropSchema>
}

export const PRETEXT_COMPONENT_REGISTRY = {
  Accordion: {
    directiveName: "accordion",
    props: {
      title: {},
    },
  },
  Badge: {
    directiveName: "badge",
    props: {
      label: {},
      tone: { values: ["danger", "info", "success", "warning"] },
      value: {},
    },
  },
  Callout: {
    directiveName: "callout",
    props: {
      kind: {
        values: [
          "caution",
          "danger",
          "important",
          "info",
          "note",
          "tip",
          "warning",
        ],
      },
      title: {},
    },
  },
  Image: {
    directiveName: "image",
    props: {
      alt: {},
      label: {},
      src: {},
      title: {},
    },
  },
  Diagram: {
    directiveName: "diagram",
    props: {
      caption: {},
      source: {},
      title: {},
      type: { values: ["mermaid"] },
    },
  },
  Metric: {
    directiveName: "metric",
    props: {
      label: {},
      value: { type: "display" },
    },
  },
  Tab: {
    directiveName: "tab",
    props: {
      title: {},
    },
  },
  Tabs: {
    directiveName: "tabs",
    props: {
      label: {},
    },
  },
  Video: {
    directiveName: "video",
    props: {
      controls: { type: "boolean" },
      label: {},
      loop: { type: "boolean" },
      muted: { type: "boolean" },
      src: {},
      title: {},
    },
  },
} as const satisfies Record<string, PretextComponentRegistryEntry>

export type PretextComponentKind = keyof typeof PRETEXT_COMPONENT_REGISTRY
type PretextComponentPropName = {
  [Kind in PretextComponentKind]: keyof (typeof PRETEXT_COMPONENT_REGISTRY)[Kind]["props"]
}[PretextComponentKind]
export type PretextComponentPropValue = boolean | number | string
export type PretextComponentProps = Partial<
  Record<PretextComponentPropName, PretextComponentPropValue>
>
export type PretextComponent = {
  name: PretextComponentKind
  props: PretextComponentProps
}

export type PretextComponentFallback = {
  componentName: string
  reason: string
  source: string
}

export function normalizePretextCalloutKind(value: unknown): CalloutKind | null {
  switch (String(value ?? "").toLowerCase()) {
    case "caution":
      return "caution"
    case "danger":
    case "error":
    case "failure":
      return "danger"
    case "important":
      return "important"
    case "info":
      return "info"
    case "note":
      return "note"
    case "success":
    case "tip":
      return "tip"
    case "warning":
      return "warning"
    default:
      return null
  }
}

export function parsePretextComponentMarkdown(
  value: string,
  mode: "selfClosing" | "opening" = "selfClosing"
): PretextComponent | null {
  const componentMatch = parsePretextComponentTag(value, mode)
  if (!componentMatch) return null

  const { attributes, name } = componentMatch
  if (!isPretextComponentKind(name)) return null

  const rawProps = parsePretextComponentAttributeString(attributes)
  if (!rawProps) return null
  const props = parsePretextComponentProps(name, rawProps)
  if (!props) return null

  return {
    name,
    props,
  }
}

export function readPretextComponentClosingMarkdown(value: string) {
  return /^<\/([A-Z][A-Za-z0-9]*)\s*>$/.exec(value.trim())?.[1] ?? null
}

export function parsePretextComponentTag(
  value: string,
  mode: "opening" | "selfClosing"
) {
  const source = value.trim()
  const nameMatch = /^<([A-Z][A-Za-z0-9]*)/.exec(source)
  if (!nameMatch) return null

  let quote: '"' | "'" | null = null
  for (let index = nameMatch[0].length; index < source.length; index += 1) {
    const char = source[index]

    if (quote) {
      if (char === quote) quote = null
      continue
    }

    if (char === '"' || char === "'") {
      quote = char
      continue
    }

    if (char === "<") return null

    if (mode === "selfClosing" && char === "/" && source[index + 1] === ">") {
      if (source.slice(index + 2).trim() !== "") return null
      return {
        attributes: source.slice(nameMatch[0].length, index),
        name: nameMatch[1]!,
      }
    }

    if (mode === "opening" && char === ">") {
      const attributes = source.slice(nameMatch[0].length, index)
      if (attributes.trim().endsWith("/")) return null
      if (source.slice(index + 1).trim() !== "") return null
      return {
        attributes,
        name: nameMatch[1]!,
      }
    }
  }

  return null
}

export function parsePretextComponentAttributeString(attributes: string) {
  const rawProps: Record<string, PretextComponentPropValue> = {}
  const propPattern =
    /\s*([A-Za-z][A-Za-z0-9_]*)(?:=(?:"([^"]*)"|'([^']*)'|\{([^{}]*)\}))?/gy
  let index = 0

  while (index < attributes.length) {
    if (attributes.slice(index).trim() === "") break

    propPattern.lastIndex = index
    const propMatch = propPattern.exec(attributes)
    if (!propMatch) return null

    const propName = propMatch[1]
    if (!isSafePretextComponentPropName(propName)) return null

    const parsedValue = parsePretextComponentAttributeValue({
      doubleQuoted: propMatch[2],
      singleQuoted: propMatch[3],
      expression: propMatch[4],
      isBare:
        propMatch[2] == null && propMatch[3] == null && propMatch[4] == null,
    })
    if (parsedValue == null) return null

    rawProps[propName] = parsedValue
    index = propPattern.lastIndex
  }

  return rawProps
}

function parsePretextComponentAttributeValue({
  doubleQuoted,
  expression,
  isBare,
  singleQuoted,
}: {
  doubleQuoted: string | undefined
  expression: string | undefined
  isBare: boolean
  singleQuoted: string | undefined
}): PretextComponentPropValue | null {
  if (doubleQuoted != null) return doubleQuoted
  if (singleQuoted != null) return singleQuoted
  if (isBare) return true
  if (expression == null) return null

  const literal = expression.trim()
  if (literal === "true") return true
  if (literal === "false") return false
  if (/^-?(?:0|[1-9]\d*)(?:\.\d+)?$/.test(literal)) {
    const value = Number(literal)
    return Number.isFinite(value) ? value : null
  }
  return null
}

function parsePretextDirectiveComponent(node: any): PretextComponent | null {
  const name = normalizePretextDirectiveComponentName(node.name)
  if (!name) return null

  const props = parsePretextComponentAttributes(node.attributes)
  if (!props) return null

  if (node.type === "textDirective") {
    const label = extractPretextDirectiveText(node)
    if (label) props.label ??= label
  }

  const validatedProps = parsePretextComponentProps(name, props)
  if (!validatedProps) return null

  return { name, props: validatedProps }
}

function extractPretextDirectiveText(node: any) {
  if (typeof node.value === "string" && node.value.trim()) {
    return node.value.trim()
  }

  const children = Array.isArray(node.children) ? node.children : []
  const text = children
    .map((child: { value?: unknown }) =>
      typeof child.value === "string" ? child.value : ""
    )
    .join("")
    .trim()
  return text || null
}

function normalizePretextDirectiveComponentName(
  name: unknown
): PretextComponentKind | null {
  const normalized = String(name ?? "").toLowerCase()
  for (const [componentName, definition] of Object.entries(
    PRETEXT_COMPONENT_REGISTRY
  )) {
    if (definition.directiveName === normalized) {
      return componentName as PretextComponentKind
    }
  }
  return null
}

function isPretextDirectiveComponentName(name: unknown) {
  return normalizePretextDirectiveComponentName(name) != null
}

function parsePretextComponentAttributes(
  attributes: Record<string, unknown> | null | undefined
): PretextComponentProps | null {
  const props: PretextComponentProps = {}
  const parsedProps = props as Record<string, PretextComponentPropValue>

  for (const [propName, propValue] of Object.entries(attributes ?? {})) {
    if (!isSafePretextComponentPropName(propName)) return null
    if (
      typeof propValue !== "string" &&
      typeof propValue !== "number" &&
      typeof propValue !== "boolean"
    ) {
      return null
    }
    parsedProps[propName] = propValue
  }

  return props
}

export function parsePretextComponentProps(
  name: PretextComponentKind,
  props: Record<string, unknown>
): PretextComponentProps | null {
  const definition = PRETEXT_COMPONENT_REGISTRY[name]
  const parsed: PretextComponentProps = {}
  const parsedProps = parsed as Record<string, PretextComponentPropValue>

  for (const [propName, propValue] of Object.entries(props)) {
    if (!isSafePretextComponentPropName(propName)) return null
    const propDefinition = (
      definition.props as Record<string, PretextComponentPropSchema>
    )[propName]
    if (!propDefinition) return null
    const parsedValue = parsePretextComponentPropValue(
      propDefinition,
      propValue
    )
    if (parsedValue == null) return null
    parsedProps[propName] = parsedValue
  }

  return parsed
}

function parsePretextComponentPropValue(
  propDefinition: PretextComponentPropSchema,
  propValue: unknown
): PretextComponentPropValue | null {
  switch (propDefinition.type ?? "string") {
    case "boolean":
      if (typeof propValue === "boolean") return propValue
      if (propValue === "true") return true
      if (propValue === "false") return false
      return null
    case "display":
      return typeof propValue === "string" ||
        (typeof propValue === "number" && Number.isFinite(propValue))
        ? propValue
        : null
    case "number":
      return typeof propValue === "number" && Number.isFinite(propValue)
        ? propValue
        : null
    case "string":
      if (typeof propValue !== "string") return null
      if (propDefinition.values && !propDefinition.values.includes(propValue)) {
        return null
      }
      return propValue
  }
}

export function isPretextComponentKind(
  name: string
): name is PretextComponentKind {
  return name in PRETEXT_COMPONENT_REGISTRY
}

function isSafePretextComponentPropName(propName: string) {
  if (/^on/i.test(propName)) return false

  return ![
    "children",
    "component",
    "dangerouslySetInnerHTML",
    "render",
    "style",
  ].includes(propName)
}

export function remarkPretextComponentDirectives() {
  return function transform(tree: unknown) {
    visit(
      tree as any,
      ["containerDirective", "leafDirective", "textDirective"],
      (node: any) => {
        const keepsChildren = node.type === "containerDirective"
        const component = parsePretextDirectiveComponent(node)
        if (!component) {
          if (isPretextDirectiveComponentName(node.name)) {
            const fallback = createPretextComponentFallbackData({
              componentName:
                normalizePretextDirectiveComponentName(node.name) ??
                "Component",
              reason: "Unsupported component directive props",
              source: serializePretextDirectiveFallback(node),
            })
            node.type = "pretextComponentFallbackDirective"
            node.data = {
              ...node.data,
              hName: "div",
              hProperties: fallback,
            }
            node.children = []
          }
          return
        }

        node.type = "pretextComponentDirective"
        node.data = {
          ...node.data,
          hName: "div",
          hProperties: {
            ...node.data?.hProperties,
            dataPretextComponentName: component.name,
            dataPretextComponentProps: JSON.stringify(component.props),
          },
        }
        if (!keepsChildren) {
          node.children = []
        }
        delete node.value
      }
    )
  }
}

function serializePretextDirectiveFallback(node: any) {
  const prefix =
    node.type === "textDirective"
      ? ":"
      : node.type === "containerDirective"
        ? ":::"
        : "::"
  const text = extractPretextDirectiveText(node)
  const label = text ? `[${text}]` : ""
  return `${prefix}${node.name ?? ""}${label}${serializePretextDirectiveAttributes(
    node.attributes
  )}`
}

function serializePretextDirectiveAttributes(
  attributes: Record<string, unknown> | null | undefined
) {
  const entries = Object.entries(attributes ?? {})
    .filter((entry): entry is [string, string] => typeof entry[1] === "string")
    .map(([name, value]) => `${name}="${value.replace(/"/g, '\\"')}"`)

  return entries.length ? `{${entries.join(" ")}}` : ""
}

export function remarkPretextComponentMarkdown() {
  return function transform(tree: any) {
    transformPretextComponentMarkdownChildren(tree)
  }
}

function transformPretextComponentMarkdownChildren(parent: any) {
  const children = Array.isArray(parent?.children) ? parent.children : null
  if (!children) return

  for (let index = 0; index < children.length; index += 1) {
    const node = children[index]

    if (node?.type === "html" && typeof node.value === "string") {
      const component = parsePretextComponentMarkdown(node.value)
      if (component) {
        children[index] = createPretextComponentMarkdownNode(component, [])
        continue
      }

      const opening = parsePretextComponentMarkdown(node.value, "opening")
      if (opening) {
        const closingIndex = findPretextComponentClosingIndex(
          children,
          index + 1,
          opening.name
        )
        if (closingIndex !== -1) {
          const componentChildren = children.slice(index + 1, closingIndex)
          const componentNode = createPretextComponentMarkdownNode(
            opening,
            componentChildren
          )
          children.splice(index, closingIndex - index + 1, componentNode)
          transformPretextComponentMarkdownChildren(componentNode)
          continue
        }
      }

      if (isPretextMdxLikeHtml(node.value)) {
        children[index] = createPretextComponentMarkdownFallbackNode(node.value)
        continue
      }
    }

    transformPretextComponentMarkdownChildren(node)
  }
}

function findPretextComponentClosingIndex(
  siblings: any[],
  startIndex: number,
  name: PretextComponentKind
) {
  let depth = 0

  for (let index = startIndex; index < siblings.length; index += 1) {
    const sibling = siblings[index]
    if (sibling?.type !== "html" || typeof sibling.value !== "string") continue

    const opening = parsePretextComponentMarkdown(sibling.value, "opening")
    if (opening?.name === name) {
      depth += 1
      continue
    }

    if (readPretextComponentClosingMarkdown(sibling.value) === name) {
      if (depth === 0) return index
      depth -= 1
    }
  }

  return -1
}

function createPretextComponentMarkdownNode(
  component: PretextComponent,
  children: any[]
) {
  return {
    type: "pretextComponent",
    data: {
      hName: "div",
      hProperties: {
        dataPretextComponentName: component.name,
        dataPretextComponentProps: JSON.stringify(component.props),
      },
    },
    children,
  }
}

function createPretextComponentMarkdownFallbackNode(value: string) {
  const fallback = describePretextComponentMarkdownFallback(value)
  return {
    type: "pretextComponentFallback",
    data: {
      hName: "div",
      hProperties: createPretextComponentFallbackData(fallback),
    },
    children: [],
  }
}

function describePretextComponentMarkdownFallback(
  value: string
): PretextComponentFallback {
  const source = value.trim()
  const componentName = readPretextComponentTagName(source) ?? "Component"
  return {
    componentName,
    reason: getPretextComponentFallbackReason(source, componentName),
    source,
  }
}

function createPretextComponentFallbackData(
  fallback: PretextComponentFallback
) {
  return {
    dataPretextComponentFallbackName: fallback.componentName,
    dataPretextComponentFallbackReason: fallback.reason,
    dataPretextComponentFallbackSource: fallback.source,
  }
}

function readPretextComponentTagName(value: string) {
  return /^<\/?([A-Z][A-Za-z0-9.]*)/.exec(value.trim())?.[1] ?? null
}

function getPretextComponentFallbackReason(
  source: string,
  componentName: string
) {
  if (componentName.includes(".")) {
    return "Remote or namespaced components are not supported"
  }

  if (!isPretextComponentKind(componentName)) {
    return "Unsupported component"
  }

  if (/\s\w+=\{[^{}]*(?:\(|\)|\w)[^{}]*\}/.test(source)) {
    return "Component props must be literal values"
  }

  if (/\s\{\s*\.\.\./.test(source) || /\{\s*\.\.\./.test(source)) {
    return "Spread props are not supported"
  }

  if (/\son[A-Za-z0-9_]*\s*=/.test(source)) {
    return "Event handler props are not supported"
  }

  return "Unsupported component props"
}

export function isPretextMdxLikeHtml(value: string) {
  const trimmed = value.trim()
  return (
    /^<\/?[A-Z][A-Za-z0-9.]*(?:\s|\/?>)/.test(trimmed) ||
    /\s\w+=\{/.test(trimmed)
  )
}
